# config.py
import os
import re
import warnings
from rich.console import Console
from rich.theme import Theme
import logging
from datetime import datetime, timedelta
from logging.handlers import TimedRotatingFileHandler
from core.session import SessionManager
from dotenv import load_dotenv
from pydantic import BaseModel, Field
import threading

# .env 파일 로드 (환경 변수 우선순위: 시스템 환경변수 > .env 파일)
load_dotenv()

# ==========================================================
# [경고 억제] yfinance × numpy 2.x DeprecationWarning
# ==========================================================
_YF_NUMPY_WARN_RE = r".*'generic' unit for NumPy timedelta is deprecated.*"


def silence_yfinance_numpy_warning():
    """yfinance(1.4.x) × numpy 2.x의 timedelta DeprecationWarning만 좁게 막는다.

      yfinance/utils.py:667  last_rows_same_interval = (dt2 - dt1) < _pd.Timedelta(interval)
      → "The 'generic' unit for NumPy timedelta is deprecated" 가 조회할 때마다 출력된다.
    지수 화면처럼 yfinance 티커를 여러 개 조회하는 경로에서는 티커 수만큼 반복돼 콘솔이 도배된다.
    동작에는 영향이 없고 라이브러리 내부라 우리 코드로는 고칠 수 없다.

    [반드시 yfinance import 뒤에 호출해야 한다]
      yfinance/__init__.py:45 가
          warnings.filterwarnings('default', category=DeprecationWarning, module='^yfinance')
      로 '자기 경고는 항상 보여준다'를 강제한다(파이썬 기본값 ignore::DeprecationWarning을 뒤집음).
      warnings 필터는 나중에 등록된 것이 앞에 놓여 먼저 매칭되므로, config import 시점에만
      걸어두면 이후 yfinance가 로드되면서 그 필터가 앞을 차지해 무력화된다.
      그래서 yfinance를 import하는 모듈마다 import 직후 이 함수를 호출한다(멱등).

    ※ 향후 numpy에서 실제 에러로 승격되면 yfinance 업그레이드가 필요하다 — 억제로 덮이지 않는다
       (에러는 warning이 아니므로 이 필터와 무관하게 예외로 드러난다).
    """
    warnings.filterwarnings("ignore", message=_YF_NUMPY_WARN_RE, category=DeprecationWarning)


# 기본선(yfinance 미로드 경로 대비). 실제 억제는 각 import 지점의 재호출이 담당한다.
silence_yfinance_numpy_warning()

# [터미널 호환] '흰색'·'회색'을 터미널 팔레트·속성에 맡기지 않고 절대색으로 고정한다.
#  - rich의 [white]는 ANSI 색 7이라 실제 색을 터미널 팔레트가 정한다. cmux(Ghostty
#    코어)는 이 값을 어둡게 그려서 '혼조(흰색)'이 회색으로 보이고 '판정 불가
#    (회색)'와 섞였다. 색 7의 표준값 #c0c0c0을 직접 박아 팔레트 의존을 끊는다.
#    순백(#ffffff, bright_white)은 cmux에서 지나치게 튀어 쓰지 않는다 — 눈에 편한
#    '살짝 어두운 흰색'이 기준이고, 회색(#808080)과는 충분히 벌어져 있다.
#  - [dim]은 색이 아니라 SGR 2(faint) '속성'이라 감쇠 정도가 터미널마다 다르다.
#    실제 회색(grey50)으로 바꿔 어느 터미널에서든 흰색과 벌어지게 한다.
#  이름을 테마에서 재정의하므로 [white]/[dim] 마크업, style=, border_style,
#  header_style이 모두 자동 적용된다 — 호출부(92곳)는 손대지 않는다.
#  (조합 스타일 [dim cyan]·[bold bright_white on yellow] 등은 rich가 속성으로 직접
#   파싱해 테마를 타지 않는다. 배경색 위 배너는 순백이 맞아 그대로 둔다.)
#  Console(style=)은 '색을 지정하지 않은 글자'(표 제목·종목명 등 기본 전경색)의
#  바닥색이다. 이걸 안 주면 그 부분만 터미널 기본 전경색(cmux는 순백)으로 남아
#  혼자 튄다. 명시적 색이 붙은 글자는 그대로 이긴다.
#  글자 밝기는 네 단계다 — 메뉴(#ffffff) > 본문/흰색(#c0c0c0) > DMI 중립(#a8a8a8)
#  > 회색(#808080). 셋 다 이름으로만 쓰고 호출부에 hex를 박지 않는다.
CONSOLE_TEXT_COLOR = "#c0c0c0"   # 어두운 배경 기준 — 밝기를 조절하려면 여기만 고친다
CONSOLE_THEME = Theme({
    "white": CONSOLE_TEXT_COLOR,
    "dim": "grey50",             # #808080 — '회색'(판정 불가·부가 설명)
    "menu": "bright_white",      # #ffffff — 메뉴 항목. 입력 프롬프트와 같은 밝기로 앞세운다
    "dmi.neutral": "grey66",     # #a8a8a8 — 중립 ●. 흰색보다 죽이되 회색보다는 밝게
})

console = Console(theme=CONSOLE_THEME, style=CONSOLE_TEXT_COLOR)

class GlobalSettings(BaseModel):
    """동적으로 변경 가능한 전역 설정값들을 관리하는 Pydantic 모델"""

    # ==========================================================
    # [설정] 현재 활성화된 전략 프리셋 (Active Preset)
    # ==========================================================
    ACTIVE_PRESET: str = "default"

    # ==========================================================
    # [설정] 스크린 디버그 로그 레벨 설정 (OFF / DEBUG / TRACE)
    # ==========================================================
    # OFF   : 로그 출력 없음
    # ERROR : [ERROR] 시스템 에러 및 정지 로그 화면 출력
    # TRACE : [TRACE] 로그 화면 출력
    # DEBUG : [TRACE], [DEBUG] 및 [ERROR] 로그 화면 출력
    SCREEN_DEBUG_LEVEL: str = "ERROR"

    # ==========================================================
    # [설정] 화면 자동 지우기 (Clear Screen)
    # ==========================================================
    # 메뉴 이동 시 이전 터미널 내용을 지우고 깔끔하게 유지할지 여부입니다.
    CLEAR_SCREEN_ON_MENU: bool = False

    # ==========================================================
    # [설정] 파일 로그 레벨 설정 (DEBUG / INFO / WARNING / ERROR / CRITICAL)
    # ==========================================================
    FILE_DEBUG_LEVEL: str = "WARNING"

    # ==========================================================
    # [설정] 텔레그램 설정 (Telegram Configuration)
    # ==========================================================
    ENABLE_TELEGRAM: bool = True
    AUTO_MORNING_BRIEFING_USE: bool = False
    AUTO_MORNING_BRIEFING_TIME: str = "0830"
    AUTO_DISCLOSURE_ALERT_USE: bool = True  # 관심종목 중대 공시 텔레그램 알림 (기본 ON)
    AUTO_CALENDAR_ALERT_USE: bool = True    # 임박 일정(경제 이벤트·배당/실적) 텔레그램 알림 (기본 ON)
    AUTO_CALENDAR_ALERT_TIME: str = "0820"  # 캘린더 알림 발송 시각 (하루 1회, D-1·D-DAY 요약)
    # [추가] 시장정지 알림: 서킷브레이커(CB)와 VI를 '독립 스위치'로 각각 ON/OFF한다.
    #  CB·VI 모두 REST 폴링이며(WS 슬롯은 현재가에 우선 배정), 사이드카는 REST 미지원으로 제외.
    #  - CB(MARKET_HALT_ALERT_USE): 시장 전체 정지. KIS 전용, 대표종목 바스켓만 조회해 부하가 작음(기본 ON).
    #  - VI(MARKET_HALT_VI_USE): 보유+관심 '종목별' 폴링이라 부하가 커서 기본 OFF.
    MARKET_HALT_ALERT_USE: bool = True      # 서킷브레이커(CB) 알림 — 시장 전체 정지, KIS 대표종목 바스켓 (기본 ON)
    MARKET_HALT_VI_USE: bool = False        # VI 발동/해제 알림 — 보유+관심 종목별 REST 폴링 (기본 OFF) — 메뉴 0 토글
    MARKET_HALT_CB_INTERVAL: int = 20       # CB 점검 주기(초) - KIS 전용
    MARKET_HALT_VI_INTERVAL: int = 30       # VI 점검 주기(초) - 보유+관심종목 (VI는 약 2분 지속)
    MARKET_HALT_VI_MAX_CODES: int = 40      # VI 점검 종목 수 상한 (라즈베리파이 부하 방어)
    TELEGRAM_INSTANCE_NAME: str = "HTS"
    TELEGRAM_POLLING_TIMEOUT: int = Field(default=10, gt=0)
    #  [명령 신선도] 텔레그램은 봇이 죽어 있는 동안 온 메시지를 최대 24시간 큐에 쌓아
    #  두었다가 재기동 첫 폴링에서 한꺼번에 내려준다. 이 값보다 오래된 명령은 실행하지
    #  않고 버린다 — 어제 보낸 /stop 이 오늘 아침 기동과 함께 되살아나면 안 된다.
    TELEGRAM_COMMAND_MAX_AGE_SEC: int = Field(default=180, gt=0)

    # ==========================================================
    # [설정] 시스템 트레이딩 (System Trading)
    # ==========================================================
    # 자동매매 모니터링 주기 (초)
    # - 너무 짧으면(예: 10초) API 호출 제한(Rate Limit)에 걸릴 수 있습니다.
    # - 너무 길면(예: 300초) 급변하는 시세에 대응하기 어렵습니다.
    SYSTEM_TRADING_INTERVAL: int = Field(default=60, gt=0)

    # [종목당 최대 투자 비중]
    # 전체 자산 대비 한 종목에 투자할 최대 비중입니다. (기본값: 0.0 = 자동)
    # - [자동 모드] 0으로 두면 (1.0 / SYSTEM_MAX_HOLDINGS)로 자동 계산됩니다.
    #   슬롯 수만 바꿔도 명목합(비중×종목수)이 항상 100%로 유지되므로, 두 값을 쌍으로
    #   맞춰야 하는 실수(0.3×4=1.2 → 앞순위 종목이 현금을 과다 소진해 뒷순위 슬롯이 굶음)가 없습니다.
    #   실효 비중 확정은 resolve_invest_ratio()가 담당합니다.
    # - [수동 모드] 0보다 큰 값을 넣으면 그 값이 그대로 쓰입니다(자동 무시).
    #   명목합을 100% 미만으로 두어 현금 버퍼를 남기거나(예: 4슬롯 × 0.2 = 80%),
    #   반대로 100%를 넘겨 '슬롯은 넓게 열되 앞순위가 현금을 먼저 쓰게' 두는 의도적
    #   오버커밋도 가능합니다. 저장 시 명목합이 100%를 넘으면 경고만 표시하고 막지는 않습니다.
    # - 리스크 기반 사이징(SYSTEM_RISK_PER_TRADE)·변동성 타겟팅(TARGET_VOLATILITY)과 함께 쓰이며,
    #   셋이 각자 낸 상한 중 '가장 적은 금액'이 최종 투자금이 됩니다(min 결합, 곱셈 중첩 아님).
    #   ※ 이 값은 '집중도'를 정할 뿐 '투자율'은 정하지 못합니다 — 명목합이 100%면
    #     4×0.25든 3×0.33이든 만재 투자율은 같고, 실제 투자율은 TARGET_VOLATILITY가 결정합니다.
    # - 만약 리스크 기반 사이징만 전적으로 따르고 싶다면 이 값을 1.0(100%)으로 설정하세요.
    SYSTEM_INVEST_PER_STOCK: float = Field(default=0.0, ge=0.0, le=1.0)
    # ==========================================================
    # [2026-08-17 · 의도적 오버커밋 검증 · tools/audit_overcommit.py] — 기각
    # ==========================================================
    #  [왜 쟀나] 목적은 '최초 진입 시 매수액을 늘리는 것'이었고, 수단으로 슬롯 4 → 3이
    #   제안됐다. 그런데 슬롯 축소는 두 가지를 동시에 한다 — ① 기초 비중이 1/4 → 1/3으로
    #   올라 진입액이 33% 커지고 ② 동시 보유 종목이 하나 줄어 승자 포착 기회가 준다.
    #   종전 슬롯 감사(2/3/5 기각)는 둘을 묶어서 쟀으므로 어느 쪽이 결과를 만들었는지
    #   몰랐다. 진입액만 키우고 슬롯은 지키는 길(오버커밋)은 아무도 재지 않았다.
    #  [격자] 2요인 5칸. 44종목·폐지 20% 혼합·10년·3구간.
    #    A [기준선] 4슬롯×0.25(명목100%) · B 4×0.30(120%) · C 4×0.333(133%)
    #    D 3×0.333(100%, 원안) · E [대조] 3×0.25(75%, 슬롯만 축소)
    #  [불변식 — 오버커밋은 상한을 깨지 않는다] 전 팔 리스크 한도 위반 0건, 1회 최대
    #   리스크 2.46% < 한도 4.0%. 즉 기각 사유는 위험이 아니라 성과다.
    #  [결과 — 오버커밋 B·C 기각. 씨드 두 집합에서 견고하다]
    #    전체창만 보면 이긴다(C 260.8% vs 기준 212.8%, 24-0-12). 그러나 **구간1에서
    #    일관되게 대패**한다 — 씨드① B 8-0-28 · C 7-0-29 / 씨드② B 18-0-57 · C 13-0-62.
    #    전체창 우세는 구간1의 손실을 구간2·3이 덮은 것이다. 채택 기준(구간이 갈리면
    #    채택하지 않는다) 불통과. MDD도 -40.7 → -47.0으로 악화한다.
    #  [2026-08-18 계측기 수정 후 재실행 · 정정] 위 '**구간1에서 일관되게 대패**'가
    #    재현되지 않는다. 다시 재니 구간1은 4슬롯×0.30 19-0-17 · 4슬롯×0.333 20-0-16으로
    #    오히려 근소 우위다(구간2 18-0-18·20-0-16, 구간3 24-0-12·20-0-16, 전체 26-0-10·25-0-11).
    #    기각은 유지하되 **근거는 구간1이 아니라 MDD 하나다** — -39.0 → -45.7 / -48.5로
    #    6.7~9.5%p 악화한다. 노출 확대 축은 셋 모두(증액 5차·오버커밋·변동성 하한) 같은
    #    형태다: 계측기를 고치면 '구간1 열위'는 사라지고 MDD 악화만 남는다.
    #  [결과 — 3슬롯(D)은 씨드에서 뒤집혔다. 종전 기각 유지]
    #    씨드①(36쌍): 세 구간 전부 21-0-15(58%) · 전체창 26-0-10 · MAR 6.15 → 7.20.
    #      → '종전 기각을 뒤집는다'고 볼 만한 그림이었다.
    #    씨드②(75쌍, 씨드 5개): 구간 33-0-42(44%) · 36-0-39(48%) · 40-0-35(53%),
    #      전체창 32-0-43(43%)로 **전부 동전던지기 이하**. 완전한 반전이다.
    #    → [[감사 씨드 견고성]]이 예방하려던 바로 그 실수다. 58%대 결과를 단일 씨드
    #      집합으로 채택했다면 슬롯을 잘못 옮겼다. **슬롯 4 유지.**
    #  [일치하는 것] MDD는 두 실행 모두 같은 방향이다 — 3슬롯 -40.4 → -42.8, 오버커밋
    #    -46.7. 노출을 키우든 집중을 높이든 MDD는 나빠진다.
    #  [남은 진단 — 총 노출은 국면 베팅일 뿐 우위가 아니다] 현금 비율로 팔이 갈린다:
    #    A 63.0% · D 63.4%(명목 100%) vs B 58.5% · C 56.1%(확대) vs E 70.2%(축소).
    #    노출을 키운 팔은 구간2·3에 강하고 구간1에 약하며, 줄인 팔(E)은 정확히 반대다
    #    (씨드② 구간1 45-0-30 승, 전체창 29-0-46 패). 어느 쪽도 전 구간 우위가 아니다.
    #  [실행 지침] 진입액을 늘리는 세 경로 중 둘(오버커밋·슬롯 축소)은 기각됐다. 남은
    #    것은 **시드 증액**이다 — 사이징 3층이 모두 자산 비례라 구조를 한 줄도 안 바꾸고
    #    진입액이 비례해 커지고, MDD도 나빠지지 않는다([[시드·슬롯 사이징]]).
    # ==========================================================
    # [2026-08-17 · '슬롯마다 똑같이 나눈다'는 전제를 처음 흔들었다 · tools/audit_allocation.py]
    # ==========================================================
    #  스코어링에 그렇게 공을 들여 놓고 정작 크기에는 반영하지 않는다 — 9점 후보와 7점
    #  후보에 같은 돈이 들어간다. run_portfolio에 invest_ratio_fn 훅을 넣어 재봤다
    #  (10년·12회×씨드3, 36쌍, 배수는 0.6~1.5배로 제한):
    #    균등(현행) 287.6%/MAR 9.21 · **점수 가중 370.1%/10.85 (29-0-7)** ·
    #    변동성 역가중 263.6%/7.47 (14-0-22) · 점수×변동성 310.8%/8.89 (22-0-14)
    #  [미채택 · 강한 리드로 남긴다] 점수 가중은 전체창 +82.5%p로 크게 이기지만
    #   **구간이 갈린다**(구간1 13-0-23 패 · 구간2 17-0-19 패 · 구간3 27-0-9 승) 그리고
    #   MDD가 -32.3 → -35.2로 악화된다. 기존 잣대(구간이 갈리면 채택하지 않는다)를 따른다.
    #   다만 TS 콜백 4.5와 달리 **최근 구간에서 이기는** 쪽이라 성격이 다르다 —
    #   되살리려면 구간1·2의 열위(고변동·하락 국면에서 큰 포지션이 더 크게 다친다)를
    #   먼저 설명해야 한다. 배수 상한을 1.5 → 1.2로 좁혀 MDD 악화를 줄이는 변형이 다음 후보.
    #
    # [2026-08-17 · 계단식 증액 후속 · tools/audit_score_weighted_sizing.py]
    #  위 리드를 '문턱을 넘은 종목만 조금 더'로 다듬어 다시 쟀다. 크기 신호로 무엇을 쓸지도
    #  함께 물었다 — 진입→청산 11,860건의 실현 손익:
    #    · 진입 점수는 단조하지 않다(7.0~7.5 -1.06% · 8.0~8.5 -2.11% · 8.5+ -0.10%).
    #    · 추세품질(TQ)은 갈린다 — 강함(60+) 평균 +0.81%·상위10% 46.0·승률 22.5% vs
    #      양호(30~60) -2.28%·16.3·10.8%. **크기 신호로는 점수보다 TQ가 낫다.**
    #      다만 양호 구간이 최악이라 단조가 아니다 → 계단은 '강함' 하나만 의미가 있다.
    #  팔 비교(36쌍, 기준선 균등 287.6%/MAR 9.21/MDD -32.3):
    #    TQ 강함+20% 314.1/9.91/-33.0 (25-0-11) · TQ 계단(+30/+15) 317.1/9.90/-33.3 ·
    #    점수 계단(+20/+10) 318.2/9.24/-35.2 · 연속 상한1.2 319.0/9.90/-33.1 ·
    #    **TQ 강함&점수8+ +20% 314.4/9.98/-32.8 (27-0-9)** · [대조] 전 종목 +10%
    #    295.6/8.86/-34.3 (22-0-14).
    #  [대조군이 핵심] 그냥 +10%도 전체창은 이기지만 MAR은 9.21 → 8.86으로 **나빠진다**.
    #   선별 증액만 MAR이 올라간다 — 이긴 것이 '노출 확대'가 아니라 '선별'임을 보여준다.
    #  [그래도 미채택] 모든 변형이 구간2에서 6~7/36으로 진다(코로나 급락 + 2022 약세).
    #   추세품질이 높은 종목은 이미 많이 오른 종목이라 급락장에서 더 크게 다친다.
    #   노출 중립 재분배(+20/-20%)도 구간2는 7-0-29로 똑같이 졌다 — 노출 문제가 아니라
    #   국면 문제다.
    #
    # [2026-08-17 · 국면 조건부 증액도 구간2를 못 살렸다 · 같은 도구 --only 1,3]
    #  PendDown/Bear(거래일의 44.1%)에는 증액을 접고 평시에만 얹었다. 전체창은 좋아진다:
    #    TQ 강함+20%·국면조건 313.6%/MAR 9.84/MDD -32.8 (28-0-8) ·
    #    **TQ+점수8·국면조건 317.7%/9.99/-32.7 (28-0-8)** vs 균등 287.6%/9.21/-32.3.
    #    구간1도 24~25/36으로 개선(무조건 팔은 22/36).
    #  [그래도 미채택 — 구간2가 그대로다] 7-0-29 · 8-0-28. 결정적 단서는 **같은 구간2에서
    #   [대조] 건전일 전 종목 +10%는 21-0-15로 이긴다**는 것이다. 즉 그 구간에서 손해를
    #   본 것은 '증액'이 아니라 '추세품질 상위 종목을 골라 증액한 것'이다. 코로나 급락과
    #   2022 약세를 지나며 직전 승자가 무너지는 모멘텀 크래시 구간이고, 우리가 쓰는 국면
    #   라벨(PendDown/Bear)은 그 구간을 짚어내지 못한다.
    #  [되살리려면] 모멘텀 크래시 감지(예: 지수 대낙폭 직후 반등 구간)에서 증액을 해제하는
    #   조건이 필요하다. 그 감지기를 새로 들이는 비용과 값어치를 먼저 따질 것.
    #  ※ [측정 함정] 첫 시도에서 조건을 '리스크 배수 <1.0'으로 썼더니 거래일의 88.5%가
    #    걸렸다(휩소율 배수가 연속값이라 거의 매일 1.0을 살짝 밑돈다). 증액이 통째로
    #    사라져 314.1% → 279.6%가 됐다. 조건을 만들면 그 조건이 며칠에 걸리는지부터 셀 것.
    #
    # [2026-08-17 · 모멘텀 크래시 감지기 4라운드 · 같은 도구 --only 4]
    #  구간2를 살릴 마지막 후보였다. 결론은 **감지기는 만들 수 있지만 구간2는 못 고친다.**
    #  ① 감지기는 '낙폭'이 아니라 '속도'로 잡아야 한다. 252일 고점 대비 낙폭(-15%/-20%)은
    #     커버리지가 62~77%였다 — 코스닥은 10년 대부분을 고점 -15% 아래에서 보내므로
    #     그 조건은 크래시가 아니라 평상시를 뜻한다. 20일 수익률 -12%(급락)로 바꾸니
    #     커버리지 19~30%가 되고 구간에도 고르게 퍼진다(한 구간에 몰리면 곡선 맞추기다).
    #  ② [진단이 팔보다 많은 것을 말했다] 크래시 창 안팎의 실현 손익(11,860건):
    #     · 급락 -12% 합집합(30.4%) : 창 안 TQ강함 **+1.97%** vs 창 밖 TQ강함 +0.43%
    #     · 반등 구간만(25.8%)      : 창 안 TQ강함 **+2.19%** vs 창 밖 +0.36%
    #     · 낙폭&고변동(16.7%)      : 창 안 TQ강함 +1.87% vs 창 안 그 외 -5.31%
    #     즉 **급락 직후는 추세품질 상위 종목이 가장 잘 버는 구간이다.** 가설(승자가 가장
    #     크게 무너진다)은 이 시스템에서 셋 다 반증됐다 — 이미 시장 필터·국면 배수가
    #     급락장 진입을 막고 있어, 그 문턱을 넘어 들어온 강추세 종목은 오히려 살아남는다.
    #  ③ 유일하게 가설과 맞는 감지기는 **양시장 동시 급락**(코스피·코스닥 교집합, 19.2%):
    #     창 안 TQ강함 -2.62% < 창 안 그 외 -1.64%, 창 밖은 +1.36% > -0.69%로 **뒤집힌다.**
    #     이 감지기로 증액을 해제하면 전체창 **319.2%/MAR 10.09/MDD -32.7 (30-0-6)**로
    #     이번 실험 전체의 최고 성적이 나온다(무조건 314.4/9.98/27-0-9).
    #  [그래도 미채택] 구간2는 7-0-29로 **한 칸도 움직이지 않았다**(무조건 6-0-30).
    #   감지기를 바꿔도, 뒤집기(창 안에서 -20%)로 가도 구간2는 그대로다. 반면 [대조]
    #   전 종목 +10%는 구간2에서 22-0-14로 이긴다. 세 라운드 내내 같은 그림이다 —
    #   구간2에서 지는 것은 증액의 조건이 아니라 **'추세품질로 고르는 것' 자체**이고,
    #   그것은 증액 다이얼이 아니라 랭킹·스코어링 축의 문제다. 여기서 감지기를 더
    #   깎는 것은 구간2를 손으로 지우는 일이 된다.
    #  [남기는 것] 크기 신호로는 TQ가 점수보다 낫다(진단 ②는 그 자체로 재사용 가능하다).
    #   증액 축은 여기서 닫는다 — 되살리려면 '구간2에서 TQ 상위가 지는 이유'를 랭킹
    #   쪽에서 먼저 풀어야 한다.
    #
    #  [함께 기각] 업종 집중 제한: 같은 업종 최대 2는 3-29-4로 거의 무동작, 최대 1은
    #   16-0-20 열위(270.5%). 가격 상관 필터(0.7)가 이미 그 일을 하고 있다.
    #  [함께 기각] 청산 후 재진입 쿨다운: 3일 15-0-21 · 5일 16-0-20 · 10일 19-0-17로
    #   전부 혼조이고 10일은 구간2에서 12-0-24로 진다. '판 종목을 다시 사는 것'은
    #   이 시스템에서 문제가 아니다(당일 재진입 허들이 이미 최악의 경로를 막는다).

    # [최대 보유 종목 수]
    # 포트폴리오에 담을 수 있는 최대 종목 개수입니다. (기본값: 4)
    # - SYSTEM_INVEST_PER_STOCK이 자동(0)이면 이 값 하나만 바꾸면 비중까지 함께 조정됩니다.
    # - [추세추종] 슬롯당 투입액(시드×25%)이 '2주 이상 매수 + 피라미딩(보유량 50% 증액) 작동'
    #   하한을 확보하면서, 승률 ~26% 구조에서 동시 보유 중 승자가 존재할 확률(~71%)과
    #   승자 1종목의 계좌 기여(25%)의 균형점.
    # - 하한은 승자 포착 확률(1-0.74^n: 4개 70%, 3개 59%, 2개 45%), 상한은 승자 희석과
    #   유니버스 크기(관심종목 수의 15~20% 이내)가 정한다. 시드별 권장: ~200만 3개,
    #   300만~1,000만 4개, 1,500만~5,000만 5개, 5,000만+ 6개(유니버스 50종목 이상일 때).
    # - [실측 2026-08-05 / tools/audit_seed_scale.py] 시드 500만 → 1,000만 전환에 맞춰
    #   슬롯 3·5·6을 다시 쟀다(728거래일·30회 짝비교). **4를 바꿀 근거는 없다.**
    #     슬롯5 MAR승: 표본20에서 21/30이지만 표본12에서 15/30, 하위구간2에서 7/30으로 사라진다.
    #     슬롯6·슬롯3도 표본 크기마다 순위가 뒤집힌다(표본30에서는 슬롯3이 22/30) — 표본
    #     중복 부풀림이지 우열이 아니다(audit_sizing_dials·audit_oversize_guard의 같은 함정).
    #   [기계적 이유] 슬롯을 늘리면 슬롯당 배분이 다시 줄어(1,000만 기준 250만 → 200만)
    #     1주도 못 사서 버리는 진입 기회가 9건 → 17건으로 되돌아간다. 시드를 키워 얻은
    #     커버리지를 슬롯 수로 도로 쓰는 셈이라, 시드 확대는 슬롯 확대의 근거가 되지 않는다.
    # ==========================================================
    # [2026-08-16 · 관심종목 수 = 지금까지 측정한 최대 레버 · tools/audit_universe.py]
    # ==========================================================
    #  슬롯(4)은 그대로 두고 후보 풀만 넓혔다. 생존 편향 보정판(표본의 20%를 폐지 종목으로
    #  채움 — 10년 실제 폐지율 563/2,700 반영. 10년·12회×씨드3, 기준선 44종목):
    #    20종목 131.5% / MAR 3.39 (8-0-28)  |  44종목(현행) 276.4% / 8.05  |
    #    60종목 448.8% / 11.22 (23-0-13)    |  80종목 605.7% / 17.75 (30-0-6 · MAR승 28/36)
    #  구간1 28-0-8 · 구간2 24-0-12 · 구간3 27-0-9 로 셋 다 승. 대조구간(고변동)만 11-0-25 패.
    #
    #  [왜] 현금 비중이 61.6 → 58.0%로 내려간다. 44종목으로는 4슬롯을 상시 채울 후보가
    #   모자라 슬롯을 놀린다. '시드는 성과가 아니라 커버리지 문제'가 여기서 정량화됐다.
    #  [선정 기준] 시총 최상위가 아니라 **상위 500 안에서 폭넓게**. 생존자 전용 실행에서
    #   시총 상위 40 추가는 480%인데 상위500 내 무작위 40 추가는 813%였다 — 대형주는
    #   변동성이 낮아 추세추종이 덜 먹힌다. 중형주를 섞는 쪽이 유리하다.
    #  [MDD 개선은 생존 편향이었다 · 정정] 생존자 전용에서는 44→80이 MDD -34.8 → -33.1로
    #   개선되지만 폐지 20%를 섞으면 -39.1 → -40.2로 개선이 사라진다. 종목 확대는
    #   **리스크 감소 수단이 아니라 기회 포착 수단**이다.
    #  [미결 ① 해소 · 2026-08-16] 100·120종목까지 늘려도 꺾이지 않는다(폐지 20% 혼합,
    #   10년·10회×씨드3, 44종목 기준선 대비 승-무-패): 60종목 200.8%/MAR 5.08 (19-0-11) ·
    #   80종목 289.6%/7.25 (17-0-13) · 100종목 269.8%/7.40 (21-0-9) ·
    #   120종목 317.4%/7.62 (23-0-7 · MAR승 23/30). 구간1·2·3 모두 120이 승이고,
    #   현금 비중은 63.4 → 60.7%로 계속 내려간다. 다만 대조구간(고변동)은 11-0-19로 지고,
    #   80 → 120의 추가 이득은 44 → 80만큼 크지 않다. **상한을 정하는 것은 성과가 아니라
    #   미결 ②(감시 주기)다.**
    #  [풀 경계는 민감하지 않다 · 2026-08-16] 확장 후보를 시총 상위 300/500/1000 중
    #   어디서 뽑아도 44 → 80의 이득은 거의 같다(수익 배수 2.23 / 2.11 / 2.04배,
    #   승-무-패 26-0-4 / 25-0-5 / 25-0-5). 탐색 메뉴의 기본값 500은 특별한 경계가
    #   아니라 무난한 값이다. 유동성도 제약이 아니다 — 501~1000위의 일평균 거래대금
    #   중앙값이 7.8억이라 250만원 주문은 0.32%다(하위 5%인 1.0억에서도 2.4%).
    # [2026-08-17 · 재조정 주기 · tools/audit_rebalance_period.py] **재조정하라. 주기는 미정.**
    #  워크포워드가 '무엇을 담느냐'를 진짜 레버로 세웠으므로(아래) 다음 질문은 '얼마나 자주
    #  다시 고르나'다. 305종목 풀 · 8.7년 복리 · 모든 팔이 같은 구간을 덮도록 마지막 창을
    #  잘라 맞췄다(안 맞추면 짧은 주기가 더 긴 기간을 굴려 배수가 부풀려진다).
    #  [1단계 교체율 — 축이 크다] 상위 44종목이 직전 대비 몇 종목 바뀌나:
    #    3개월 24.6종목(55.9%) · 6개월 31.0(70.5%) · 12개월 33.5(76.1%) · 24개월 36.5(83.0%).
    #    3개월마다 봐도 절반 넘게 바뀐다 = 적합도 순위가 그만큼 빠르게 흔들린다.
    #    ※ 관심종목 교체는 그 자체로 거래비용이 없다(매수 후보만 바뀌고 보유는 안 판다)
    #      — 다른 회전율 축과 달리 반대급부가 없어 순수 성과로 판정할 수 있다.
    #  [2단계 성과 — 최종 배수, 풀 3개]        풀A      풀B      풀C    기하평균
    #      3개월                              6.48x    2.23x    2.65x    3.37x
    #      6개월                             18.70x    1.91x   12.38x    7.62x
    #      12개월(현행)                        6.97x    2.79x    9.45x    5.68x
    #      24개월                             4.53x    1.82x    2.75x    2.83x
    #      [기준선] 재조정 없음               1.14x    1.53x    2.86x    1.71x
    #      [대조] 무작위 고정                 1.36x    2.51x    1.79x    1.79x
    #  [채택] **재조정하는 행위 자체가 값을 한다** — 12개 체인 중 10개가 '고정'을 이긴다.
    #    양 끝은 나쁘다: 24개월 풀별 4·4·3위, 3개월 3·2·4위로 둘 다 일관 하위.
    #  [미채택] **6개월 vs 12개월은 못 가른다** — 평균 순위가 1.67로 동률이고 풀마다
    #    순서가 뒤집힌다(6개월 1·3·1위 / 12개월 2·1·2위). 현행 12개월을 바꿀 근거 없음.
    #  [경고] 풀B에서는 **무작위 고정(2.51x)이 재조정 팔 셋을 이긴다.** 아래 워크포워드의
    #    '적합도 6/6 압승'은 적합도와 무작위를 **같은 주기로 재조정했을 때**의 비교다.
    #    적합도 정렬의 우위는 풀에 따라 흔들린다 — 단일 풀로 판정하지 말 것.
    #  [실행 지침] 관심종목은 **1년에 한 번은 적합도로 다시 정렬**한다. 2년 이상 방치하지
    #    않는다. 더 자주(3~6개월) 하는 것은 해롭지 않으나 이득도 입증되지 않았다.
    #  [2026-08-19 계측기 수정 후 재실행 · 지침은 그대로, 근거 문장 두 개를 고친다]
    #    위 수치는 기본 정렬이 실매매와 다르던 계측기의 것이라 다시 쟀다
    #    ([[backtest-tiebreak-parity]]). 최종 배수(풀 3개):
    #        팔            씨드20260817   씨드31   씨드777   기하평균
    #        3개월             3.16x      1.43x    1.52x     1.90x
    #        6개월             3.09x      2.69x    3.03x     2.93x
    #        12개월(현행)       4.58x      4.95x    4.40x     4.64x   ← 세 풀 중 둘에서 1위
    #        24개월            2.23x      2.31x    7.36x     3.36x
    #        [기준선] 고정      2.62x      3.84x    5.05x     3.70x   ← 2위
    #        [대조] 무작위      1.68x      1.48x    0.98x     1.35x
    #    ① **'재조정하는 행위 자체가 값을 한다'는 재현되지 않는다.** 고정이 꼴찌(1.71x)가
    #       아니라 **2위**다 — 6개월·24개월·3개월은 고정을 못 이긴다. 값을 하는 것은
    #       '재조정'이 아니라 **'12개월 주기의 재조정' 하나**다.
    #    ② **'6 vs 12개월은 못 가른다'도 재현되지 않는다.** 12개월이 기하평균 1위이고
    #       세 풀 중 둘에서 1위다. 현행 값이 오히려 더 강해졌다 — 바꿀 이유는 여전히 없다.
    #    ③ 무작위 고정이 세 풀 모두 최하위인 것은 그대로다(적합도 정렬 자체의 값어치).
    # [2026-08-17 · 워크포워드 · tools/audit_universe_walkforward.py] **크기 레버 정정**
    #  아래 두 실험이 모두 '크기'와 '선택 편향'을 못 갈랐으므로, 양쪽 팔을 **같은 규칙으로
    #  그 시점 정보만 써서** 고르는 워크포워드로 다시 쟀다. 재조정 12개월·8창·복리 연결,
    #  풀 305종목(규칙 통과 생존 + 폐지 45)에서 적합도 상위 K를 관심종목으로 삼는다.
    #  **결과: 크기 이득이 재현되지 않는다. 풀을 바꾸면 방향이 뒤집힌다.**
    #    풀A  적합도 44 → 4.43배 · 80 → 8.45배 · 창 7-1   (80 대승)
    #    풀B  적합도 44 → 1.95배 · 80 → 2.11배 · 창 4-4   (무승부)
    #    풀C  적합도 44 → 9.17배 · 80 → 7.48배 · 창 3-5   (80 패)
    #    합계 창 14-10(58%) — 동전 던지기보다 아주 조금 나은 정도다.
    #  같은 크기의 무작위 선택도 80이 44를 못 이긴다(2-6 · 4-4 · 2-6).
    #  [왜 종전 수치가 컸나] 고정 창·고정 풀에서 44를 80의 부분집합으로 뽑는 설계는
    #   '더 많이 담으면 좋은 종목을 놓칠 확률이 준다'는 효과만 재고, 그 좋은 종목이
    #   **오늘 기준으로 이미 승자라는 사실**을 통제하지 못한다. 워크포워드가 그것을 뺀다.
    #  [대신 드러난 진짜 레버] **적합도 정렬은 세 풀 전부에서 무작위를 크게 이긴다.**
    #    44종목: 4.43 vs 1.85/1.46/3.86 · 1.95 vs 0.88 · 9.17 vs 1.95
    #    80종목: 8.45 vs 2.70/0.98/3.32 · 2.11 vs 0.51 · 7.48 vs 2.25   (6/6 압승)
    #   즉 **몇 개를 담느냐보다 무엇을 담느냐가 훨씬 크다.** 탐색 메뉴의 적합도 정렬은
    #   '아래쪽을 피하는 정도'가 아니라 그 자체로 강한 축이다(종전 결론 상향).
    #  [적용] '관심종목을 80으로 늘려라'는 **지침이 아니다.** 늘리는 것 자체는 무해하나
    #   (창 14-10) 기대할 이득이 없다. 종목을 바꿀 여력이 있다면 수를 늘리는 대신
    #   **적합도 상위로 갈아끼우는 편**이 실증이 지지하는 방향이다.
    #  ※ 풀에 따라 적합도 44의 최종 배수가 1.95~9.17배로 흩어진다 — 어떤 풀을 잡느냐가
    #    결과를 좌우한다. 단일 풀 한 번으로 이 축을 판정하지 말 것.
    #
    # [2026-08-17 · 실제 선정 규칙으로 뽑은 80종목 · tools/audit_discover_universe.py]
    #  위 크기 축의 이득은 확장 종목을 **시총 상위 500 무작위**로 뽑아 쟀다. 실제로는
    #  탐색 메뉴가 배제 규칙 + 시총 분산 선정으로 고른다. 그 규칙 그대로 뽑아 다시 쟀다.
    #  (폐지 20% 혼합, 4슬롯, 36쌍. 기준선 = **실제 관심종목 44 전부** + 폐지 11.)
    #    [기준선] 관심 44        553.8% / MAR 16.35 / 상위10% 43.3
    #    [대조]  무작위 확장 80   365.7 / 11.09 / 40.5   —  8-0-28
    #            탐색 규칙 확장 80 442.5 / 12.51 / 43.8   — 12-0-24
    #            규칙+적합도상위 80 508.5 / 14.99 / **49.9** — 16-0-20 (구간3은 25-0-11 승)
    #  [읽히는 것 둘]
    #   ① **탐색 규칙은 무작위보다 확실히 낫다**(442.5 vs 365.7, 적합도 상위는 508.5).
    #      메뉴의 배제·정렬 규칙이 값을 한다는 기존 감사와 같은 방향이다.
    #   ② 그런데 **어떤 확장도 현재 관심종목 44를 못 이긴다.**
    #  [그러나 이 비교는 결론을 못 낸다 — 기준선이 가장 크게 편향된 팔이다]
    #   관심종목 44는 오늘 시점에 사람이 고른 목록이라 과거 10년 성과가 구조적으로
    #   부풀려져 있다. 같은 조건의 **무작위 44는 211.2%**(audit_slots_x_universe)인데
    #   관심 44는 553.8%다 — 2.6배 격차가 종목 선택에서만 나온다. 확장이 '지는' 것은
    #   실력 저하가 아니라 그 편향이 희석되는 것일 수 있고, 둘을 이 실험으로는 못 가른다.
    #  [따라서] '80종목으로 늘려라'도 '늘리지 마라'도 확정할 수 없다. 크기 축의 이득
    #   (무작위 44 → 무작위 80)은 편향을 고정한 비교라 여전히 유효하지만, **그것을 실제
    #   관심종목에 그대로 적용할 근거는 아직 없다.**
    #  [해결 방법] 워크포워드 — 과거 시점에 그 시점 정보만으로 종목을 고르고 이후를
    #   돌린다. tools/audit_discover_fit.py 가 적합도 정렬에 대해 이미 그렇게 했다.
    #   같은 틀을 '유니버스 크기'로 확장하는 것이 다음 작업이다.
    #
    #  [미결 ② — 2026-08-17 해소] 파이3 운영 로그 30일치(주기 4,705회)로 직접 쟀다
    #   (tools/audit_pi_operation.py). 모델이 아니라 실기 실측이다.
    #     주기 = 고정비 4.9초 + 종목당 207ms(평시) / 380ms(혼잡 p90)
    #     44종목 추정 14초 vs **실측 p50 12.6초** — 모델이 실측과 맞는다(자체 검증).
    #     추정치:  80종목 평시 21초 · 혼잡 54초   |  120종목 평시 30초 · 혼잡 69초
    #   대기 간격이 60초이므로 **80종목까지는 혼잡할 때도 주기가 대기 안에 들어온다.**
    #   120종목은 혼잡 시 초과한다. → [[관심종목 수 레버]](44 → 80에서 수익 276 → 606%)는
    #   파이3에서 **실행 가능**하다. 상한의 실질 경계는 80~100 사이다.
    #   ※ 다만 꼬리는 종목 수와 무관하게 이미 존재한다: 주기의 3.9%가 120초를 넘고
    #     최대 343.8초 → 실제 청산 감시 간격 최대 404초(6.7분). 장중 전 시간대에
    #     고르게 퍼져 있어 개장 혼잡이 아니라 API 지연·재시도가 원인이다. 종목을 늘리면
    #     이 꼬리도 비례해 늘어나므로, 80종목 전환 시 이 지표부터 다시 볼 것.
    #   ※ 8시·16~19시(NXT 시간대)는 p50이 28~35초로 정규장(11~13초)보다 오히려 느리다.
    #
    # [2026-08-16 · 생존 편향 실측 · tools/audit_universe.py --axis B]
    #  모든 감사가 '현재 상장된' 종목에서 표본을 뽑아왔다. 폐지 40종목을 섞으면
    #  306.9% / MDD -30.1 / MAR 9.97  →  148.9% / -40.3 / 3.75.
    #  **기록된 모든 절대 수익률은 약 2배 부풀려져 있다.** 다만 다이얼 순위는 두 풀에서
    #  같아(양쪽 모두 현행 1위·콜백 좁히기 최하위) 기존 결론 자체는 안전하다. 콜백 좁히기는
    #  폐지를 섞으면 오히려 격차가 커진다(172.8 → 48.1).
    #  ※ 폐지 종목 일봉은 backtest.get_backtest_data로 그대로 조회된다(별도 인프라 불필요).
    # [2026-08-17 · 유니버스 × 슬롯 상호작용 · tools/audit_slots_x_universe.py]
    #  두 결론이 따로 서 있고 사이가 비어 있었다 — 유니버스 축(44→80)은 슬롯을 4로
    #  고정하고 쟀고, 슬롯 축(2/3/5 기각)은 44종목에서 쟀다. 후보가 두 배면 같은 4칸을
    #  두고 경쟁하는 종목이 두 배이므로 방향이 선험적으로 정해지지 않는다.
    #  격자 {44,80}종목 × {3,4,5,6}슬롯, 36쌍, 44는 80의 부분집합.
    #  [1차 = 생존 종목만] 80종목에서 3슬롯이 압도했다(567.1%/MAR 15.85 vs 4슬롯
    #   453.4/12.41). 44에서는 슬롯 곡선이 평평(MAR 6.90/6.91/6.93)해 4가 최적.
    #   → '유니버스를 늘리면 최적 슬롯이 3으로 옮겨간다'는 그림.
    #  [2차 = 폐지 20% 혼합 · 이쪽이 맞다] **그 그림이 무너진다.**
    #   80×3 355.5%/MAR 9.02 vs 80×4 336.3%/**9.77** — 수익은 3슬롯이지만 MAR은 역전.
    #   구간별로도 갈린다: 구간1 4슬롯 승 · 구간2 3슬롯 승(MAR은 동률) · 구간3 4슬롯 승.
    #   → **슬롯 변경 미채택, 현행 4 유지.**
    #  [왜 1차가 틀렸나] 집중(슬롯 축소)은 생존 편향을 **정확히 증폭하는 방향**이다 —
    #   살아남은 승자에 더 크게 베팅하는 것이기 때문이다. 80×3의 수익이 567 → 355로
    #   깎이면서 우위(+25% → +6%)가 사라졌다. [[생존 편향 2배]] 기록의 '다이얼 순위는
    #   두 풀에서 같다'는 면제는 **집중도 축에는 적용되지 않는다.** 사이징·배분·슬롯처럼
    #   집중을 바꾸는 축은 반드시 폐지 혼합으로 재확인할 것.
    #  [함께 얻은 것] 유니버스 확대 자체는 폐지 혼합에서도 견고하다 — 4슬롯 기준
    #   44종목 211.2% → 80종목 336.3%(26-0-10)이고 **구간 셋 모두 승**
    #   (구간1 20-0-16 · 구간2 25-0-11 · 구간3 20-0-16). 배수는 생존 풀의 2.2배가 아니라
    #   1.59배다 — 인용할 때 이 값을 쓸 것.
    SYSTEM_MAX_HOLDINGS: int = Field(default=4, gt=0)

    # [휩소 방어] 당일 손절로 청산한 종목을 그 손절가 **이상**에서 되사지 않는다.
    # - 배경(2026-08-05 관측): 손절 직후 같은 종목을 10초 뒤 1,000원 비싸게 재매수하는 일이
    #   매 주기 반복됐다. 매도는 즉시 체결을 위해 현재가 아래, 매수는 위로 지정가를 내므로
    #   왕복 스프레드(약 0.65%)만큼 실현 손실만 쌓인다.
    # - 기존 재진입 허들(직전 매수의 체결강도 경신)은 이 경로를 못 막는다. 재진입할 때마다
    #   허들 값이 갱신되어 스스로 세운 기준을 스스로 넘는다(실측 103.1% → 127.3% → 127.5%).
    # - 대상은 손실 청산 계열(손절·본전청산)뿐이다. 익절·트레일링 청산까지 막으면 상승 추세
    #   에서의 정상 재진입을 차단해 추세추종에 역행한다. 추세가 살아 있다면 손절가 아래
    #   눌림에서 다시 잡히므로, 이 게이트는 '판 값보다 비싸게 되사기'만 정확히 막는다.
    # [2026-08-17 · 백테스트로 옮겨 재봤다 · tools/audit_reentry_block.py] **유지. 단, 근거는
    #  성과가 아니라 관측된 병리와 무해성이다.**
    #  이 게이트는 실매매(trader.py)에만 있었고 감사 도구 69개 어디에도 없었다. pb에
    #  `reentry_block` 훅과 `reentry_blocked` 카운터를 새로 달아 60분봉 세계에서 쟀다
    #  (종가 모델은 매도·매수가 같은 가격이라 '더 비싸게 되사기'가 존재하지 않는다).
    #  [빈도가 거의 0이다] 37종목·702거래일 전체 실행에서 손절 51건·매수 144건 중
    #    **같은 날 손절+재매수는 1건**, 게이트 차단은 7건(100거래일당 1건)이었다.
    #    20종목 표본 45쌍에서는 4창 전부 **0-45-0**(차단 0건) — 표본으로는 잡히지도 않는다.
    #  [무해하다] 전체 실행 단일 경로: 수익 154.41 → 154.80%, MDD -28.16 → -28.06%,
    #    체결 365건 동일(막힌 진입은 뒤 봉에서 다시 잡히거나 다른 후보가 대신 들어간다).
    #  [그러나 필요성은 백테스트로 판정할 수 없다 — 구조적 한계] pb는 하루치 청산을 모두
    #    끝낸 뒤 진입을 스캔하므로 **손절 → 재매수 → 손절 → 재매수 루프를 만들 수 없다.**
    #    2026-08-05에 실제로 관측된 것이 바로 그 루프이고(매 60초 주기마다 반복, 왕복
    #    스프레드만 쌓임), 이 게이트가 막는 최악의 경로도 그것이다. 즉 백테스트는
    #    '무해한가'에는 답하고 '필요한가'에는 답하지 못한다.
    #  [답하려면] 파이 로그로 실제 차단 횟수와 차단된 종목의 이후 경로를 세야 한다 —
    #    진입 게이트 손익 판정과 같은 제약(로그 3개월 필요, ≈2026-11)에 걸린다.
    REENTRY_BLOCK_ABOVE_STOP_PRICE: bool = True

    # [1주 강제 매수 상한] 배분액이 1주 값에 못 미칠 때, 1주 값이 배분액의 몇 배까지면
    #  그래도 사는가. 이 배수를 넘으면 진입하지 않는다.
    # - 배경: 배분액이 1주 값보다 작으면 배분액을 1주 값까지 끌어올리는 보정이 있었는데
    #   (가용 예수금 전체를 쓰는 버그를 막으려던 것), 그 결과 변동성 타겟팅·리스크 한도가
    #   min 결합으로 합의한 상한이 1주 값 하나에 덮어써졌다. 큰 계좌에서는 발동하지 않지만
    #   시드 500만에서는 관심목록 41종목 중 7종목(17%)이 이 경로를 탄다.
    #     SK하이닉스 1,577,000원 · 목표 배분 500,000원 → 집행 1,577,000원 = 계좌의 31.5%
    #     1회 리스크 = 1,577,000 × 15% = 236,550원 = 4.7% > SYSTEM_RISK_PER_TRADE(4.0%)
    # - [파리티] 백테스트(portfolio_backtest)는 같은 상황에서 건너뛴다. 즉 이 파일에 기록된
    #   사이징·리스크 결론은 전부 '못 사면 안 산다' 모델에서 나왔는데 실매매만 달랐다.
    #
    # [실측 2026-08-05 / tools/audit_oversize_guard.py] 727거래일·30회 짝비교, 시드 500만.
    #   [불변식] 진입 순간 최대 비중  무제한 48.0% → 1.3배 25.0% (목표 25%와 일치)
    #            1회 최대 리스크      무제한 7.07% → 1.3배 1.89% (한도 4.0% 이내)
    #            고변동 구간3에서는 무제한이 45.5% / 6.49%까지 갔다.
    #   [성과] 차이 없음. 표본 20(중복 49%)에서는 초과 불허가 +13.8%p로 좋아 보이지만
    #     중복이 적은 표본 12(29%)에서는 -0.3%p·MAR승 11/30으로 사라진다 — 표본 중복
    #     부풀림이다(audit_sizing_dials.py에서 확인된 것과 같은 함정). 성과를 근거로
    #     채택하지 않는다. 채택 근거는 '정해둔 상한이 실제로 지켜지는가' 하나다.
    #   [실측 2026-08-05 / 시드 1,000만 재검증] 500만 대조군을 같은 코드로 함께 돌려
    #     기록값(48.0% / 7.07%)이 소수점까지 재현되는 것을 확인한 뒤 시드만 바꿔 쟀다.
    #       무제한  진입최대 48.0% → 25.0% · 1회 리스크 7.07% → 3.42%(한도 4.0% 이내)
    #       1.3배   진입최대 25.0% → 25.0% · 1회 리스크 1.89% → 1.86%
    #     시드가 커지면 1주 값이 배분액을 넘는 종목이 줄어 가드 발동 자체가 드물어진다
    #     (초과매수 중앙 6건 → 1건). 즉 이 가드는 1,000만에서 '거의 놀지만 무해한' 층이다.
    #     1.0(초과 불허)의 수익 이점도 500만의 +13.8%p에서 0.0으로 사라져, 아래 기각 근거가
    #     오히려 강해졌다. 시드를 더 키워도 1.3을 바꿀 이유는 없다.
    #   [1.0(초과 불허)을 쓰지 않는 이유] 하위기간에서 견고하지 않다 — 구간1에서 MAR이
    #     0.89 → 0.36으로 악화했다(진입 기회를 22건 버려 표본이 얇아진다). 1.3배는
    #     불변식은 똑같이 지키면서(진입최대 25.0%) 구간1 MAR 0.86으로 현행과 대등하고,
    #     현 국면과 닮은 구간3에서 MAR승 26/30으로 가장 안정적이었다.
    # - 1.0으로 두면 초과 집행을 아예 허용하지 않는다(백테스트 종전 동작).
    #   값을 크게 둘수록 종전 실매매(무제한)에 가까워진다.
    MAX_POSITION_OVERSHOOT: float = Field(default=1.3, ge=1.0)

    # [추가] 자동매매 대상에 ETF 포함 여부
    # 기본값: False (관심종목 중 국내 주식만 시스템 트레이딩 대상으로 함)
    # [2026-08-17 · 근거 확보 · tools/audit_etf_inclusion.py] 이 스위치는 감사 도구 69개
    #  어디에도 등장하지 않았다 — 기본값이 그냥 False였고 근거가 없었다. **False 유지 확정.**
    #  [사전 진단 — '진입액이 커진다'는 동기는 기각] ETF도 19/20이 변동성 하한에 눌린다
    #    (ATR/가격 중앙 ETF 5.27% vs 주식 6.61%, 진입액 둘 다 100만원). 담고 있는 것이
    #    업종·테마 ETF(KODEX 은행·TIGER 화장품 등)라 개별주만큼 흔들린다. 시장 전체
    #    ETF였다면 배수가 하한을 벗어나지만 그런 종목은 목록에 없다.
    #  [핵심 대조 D vs E — 같은 64종목에서 ETF 20 추가 vs 주식 20 추가] 36쌍·10년
    #    승-무-패  전체 10-26 · 구간1 6-30 · 구간2 16-20 · 구간3 14-22 → **4창 전부 열위**
    #    수익      232.3% vs 422.8% · MAR 6.56 vs 12.03
    #  [기각 사유는 꼬리다] 상위10% 수익이 ETF를 넣을수록 얇아진다 — 주식44 33.7 →
    #    ETF10 치환 32.4 → ETF20 치환 30.0(대조 주식64는 36.9). ETF는 이미 분산돼 있어
    #    큰 승자가 안 나오는데 이 시스템은 꼬리가 계좌를 끈다. 지주회사 배제와 같은 논리다.
    #  [MDD는 ETF가 낫다] -38.3 → -34.2%. 그러나 MAR로 봐도 대조군에 크게 지므로
    #    '방어 수단으로 ETF를 섞는다'는 절충도 성립하지 않는다.
    #  ※ [읽을 때 주의] 위 표의 '주식 64' 팔이 422.8%로 기준선(228.8%)을 압도하는 것을
    #    '종목을 늘려라'로 읽지 말 것 — 확장 풀이 오늘 시총 상위 500의 생존자라서 생기는
    #    편향이고, 워크포워드가 이미 정정했다(위 재조정 주기 블록 참조). 이 실험에서
    #    유효한 것은 같은 편향을 공유하는 D vs E 비교뿐이다.
    #  [2026-08-18 계측기 수정 후 재실행 · 결론 불변] 위 수치는 기본 정렬이 실매매와
    #    다르던 시절의 것이라(점수만 보고 동점은 등록 순서, [[backtest-tiebreak-parity]])
    #    다시 쟀다. 실매매 동점가름 + 워밍업 절단으로 36쌍·10년:
    #      D vs E 승-무-패  전체 6-30 · 구간1 16-20 · 구간2 10-26 · 구간3 10-26
    #      수익 336.4% vs 542.6% · 상위10% 39.7 vs 45.6 (꼬리가 얇아지는 형태도 그대로)
    #    구간별 숫자는 옮겨 다니지만 **네 창 전부 열위**라는 판정과 기각 사유(꼬리)는
    #    바뀌지 않았다. False 유지 — 재제안 불필요.
    SYSTEM_INCLUDE_ETF: bool = False

    # [추가] 실시간 시세 WebSocket 사용 여부 (KIS mode 1/2)
    # 기본값: True. 켜면 보유/관심 종목 현재가·체결강도를 WebSocket push로 받아 REST/TPS 부담을 줄인다.
    # 미구독/끊김/비활성 시 자동으로 기존 REST 조회로 폴백한다. (토스 mode 3는 공식 미지원→REST 유지)
    USE_WEBSOCKET: bool = True

    # [추가] 매매일지 웹서버 연동 사용 여부 (메뉴 0 → 5-3 에서 토글)
    # 기본값 False. 켜더라도 JOURNAL_API_URL/JOURNAL_API_KEY 환경변수가 모두 있어야 실제로 동작한다.
    # 끄면 체결 기록이 전송 대기열(journal_outbox)에 쌓이지도 않고 워커도 기동하지 않는다.
    JOURNAL_SYNC_USE: bool = False

    USE_MARKET_FILTER: bool = True          # 장세 판단 필터 사용 여부 (코스피 지수 추세 확인)
                                            # [주의] 이 토글은 신규 매수 게이트 하나만 끄는 것이 아니다.
                                            #   피라미딩의 시장 게이트도 함께 풀린다 — trader._try_pyramid_buy의
                                            #   조건이 `USE_MARKET_FILTER and PYRAMIDING_REQUIRE_HEALTHY_MARKET`
                                            #   이라 앞이 False면 뒤는 평가되지 않는다. 설정 화면에는
                                            #   PYRAMIDING_REQUIRE_HEALTHY_MARKET이 true로 보이는데 실제로는
                                            #   작동하지 않아 눈에 띄지 않는다. 즉 필터 OFF는 '약세장에 진입한다'가
                                            #   아니라 '약세장에서 진 포지션에 50%씩 3차까지 더 넣는다'가 된다.
                                            #   [실측 2026-08-05] 727거래일·30회 짝비교(시드 500만·슬롯4):
                                            #     증액 54회 → 72.5회(+34%), MDD 중앙 -26.8% → -32.1%,
                                            #     MAR 5.59 → 4.64, 평균 현금 47.9% → 32.6%.
                                            #     (수익은 오히려 +3.1%p — 필터는 수익이 아니라 손실 폭을 자르는 장치다.
                                            #      MARKET_FILTER_MA의 2026-08-03 검증 ①과 같은 결론을 독립 재현한 것)
                                            #   반면 국면·휩소율·드로다운 리스크 배수는 영향받지 않는다 —
                                            #   _update_risk_scale은 market_index_status가 아니라
                                            #   analysis.get_market_regime_detail()을 따로 부르기 때문이다.
    # [추세추종 검증] 상대강도(RS) 필터 — 기본 OFF. 실증 결과 추세 초입 진입을 막는 역효과가 확인되었다.
    #   운영 유니버스 37종목×9년(2016~2026)의 실제 매수 신호 10,307건 검증:
    #   RS>0 게이트는 신호의 28.6%를 차단하면서 대박(120일 +30%↑) 비율 26.6%→25.4%,
    #   손실(-10%↓) 24.1%→25.0%, MDD -14.33%→-14.71%로 모든 지표를 악화시켰다.
    #   원인은 지수가 먼저 오른 국면에서 뒤늦게 돌아서는 종목(=추세 시작)이 항상 '지수 대비 열위'로
    #   찍히는 것 — 지수 126일 모멘텀 +20%↑ 구간의 차단율이 39.9%로 최고인데, 그때 차단된
    #   980건은 48.6%가 +30% 이상 대박이었다. RS 구간별 성과도 비단조(RS≤-30 구간의 대박률
    #   43.9%가 전 구간 최고)라 임계값 게이트로 성립하지 않는다.
    #   유효 성분은 전부 종목 '절대' 모멘텀이 갖고 있고(스코어링 '가격 모멘텀' 팩터로 이미 반영),
    #   절대 모멘텀 게이트에 RS를 덧붙이면 오히려 전 지표가 나빠진다(대박 28.7%→26.8%).
    #   설정 키와 게이트 로직은 유지하되 메인메뉴 0에서는 숨긴다(ANTI_TREND_HIDDEN_KEYS).
    USE_RS_FILTER: bool = False
    RS_FILTER_LOOKBACK: int = Field(default=0, ge=0)  # RS 필터 수익률 비교 룩백(거래일). 0이면 스코어링 '가격 모멘텀' 룩백(MOMENTUM_LOOKBACK, 기본 126일)과 자동 연동
    MARKET_FILTER_MA: int = Field(default=80, gt=0)              # 시장 필터링 기준 단순이동평균선 (SMA, 일)
                                            #   지수 일봉은 KIS 2년치·토스/tvDatafeed 260봉을 받으므로 이 기간은 여유 있게 충족된다
                                            #   (get_domestic_index_data가 이 값 미만인 소스는 건너뛰고 다음 소스로 폴백).
    # [검증 2026-08-03 / 60 → 80] 지수 21년(2005~2026) + 실제 매수신호 19,477건(2016~2026) +
    #  포트폴리오 백테스트 경로 234개(9구간 × 13포트폴리오 × 2회차, 슬롯4·피라미딩3차·시드 500만).
    #   ① 필터 자체는 유지가 맞다 — 필터 OFF는 CAGR 중앙 -2.20%·MDD -38.2%·PF 0.76으로 압도적 열위.
    #   ② 짧게 가면 나빠진다 — SMA40은 SMA60 대비 경로 승률 41.9%(ΔCAGR -1.01%p). 휩소 우려는 실증됐다.
    #   ③ 60일의 실제 문제도 휩소였다 — KOSPI 차단 에피소드 연 7.6회·중앙 길이 3.5일·59%가 5일 이하,
    #      82%가 '차단 구간 동안 지수 상승'(헛경보). 국면 판단이 아니라 눌림목 매수중단으로 동작했다.
    #   ④ 80일이 최적 고원의 중심 — SMA60 대비 경로 승률 74.4%, ΔCAGR +2.43%p, ΔMDD +3.07%p이고
    #      9개 검증 구간 전부에서 지지 않은 유일한 값이다(SMA100/120은 평균은 낫지만 2019-2022·
    #      2023-2026 구간에서 각각 -2.5%p·-8.4%p로 크게 진다).
    #   ⑤ 150일 이상은 금지 — KOSPI -15% 이상 조정 9회 중 3회를 아예 감지하지 못했다(80일은 1회).
    #      방어층으로서 실격이다. 편집 상한도 이 근거로 120으로 조인다(settings._RANGE_MAP).
    #  ※ 지연 비용은 실재하나 작다: 80일은 하락이 평균 43% 진행된 시점(12일)에 차단, 60일은 40%(10일).
    #    이 게이트는 신규 진입만 막고 보유분 청산은 ATR 손절·샹들리에 TS가 담당하므로,
    #    지연 비용이 휩소 비용보다 구조적으로 작다.
    # [2026-08-18 재실행 · tools/audit_market_filter_period.py(신규)] 위 근거의 한 축인
    #  '포트폴리오 백테스트 경로 234개'를 만든 도구가 남아 있지 않았고, 당시 계측기는
    #  기본 정렬이 실매매와 달랐다([[backtest-tiebreak-parity]]). 시장 필터는 진입을 통째로
    #  막는 팔이라 순위에 정면으로 닿으므로 도구를 새로 만들어 다시 쟀다.
    #  (10년 · 폐지 20% 혼합 44종목 · 36쌍 · 실매매 동점가름 · 워밍업 절단, 기준선 = 필터 OFF)
    #    팔            전체 수익/MDD    전체    구간1    구간2    구간3
    #    [OFF]         240.8 / -49.7      —     14.7%    38.5%   114.1%
    #    SMA40         168.4 / -41.3    14-22   18-18    16-20    19-17
    #    SMA60         198.4 / -38.4    16-20   22-14    17-19    16-20
    #    SMA80(현행)    286.6 / -43.9    21-15   19-17    24-12    18-18
    #    SMA100        280.6 / -43.7    23-13   25-11    21-15    18-18
    #    SMA120        240.7 / -44.0    18-18   21-15    21-15    20-16
    #    ±0%           228.8 / -41.9    20-16   24-12    23-13    15-21
    #    ±2%           305.0 / -40.4    23-13   23-13    25-11    16-20
    #    [대조] 무작위  155.9 / -49.6    55-125  87-93    81-99    85-95
    #  ① **필터라는 장치 자체는 확실히 값을 한다 — 이번에 처음 증명됐다.** 같은 수의 날을
    #    아무렇게나 막는 대조는 필터 OFF보다도 **크게 진다**(155.9 vs 240.8, 55-0-125).
    #    즉 이득은 '덜 사서'가 아니라 '지수를 보고 막아서' 나온다. 종전 근거 ①을 계측기
    #    수정 후에 다시, 그리고 더 강한 형태로 재현한 것이다.
    #  ② **60 → 80 이동은 재현된다.** 40·60은 전체·구간2에서 열위고 80은 네 창 어디서도
    #    지지 않는다. 근거 ②③④의 방향은 유지된다.
    #  ③ [SMA100 — 직접 짝비교로 기각] 위 표에서 100이 전체 23-13·구간1 25-11로 80보다
    #    나아 보였으나, 둘 다 'OFF와의 승패'라 서로 견준 것이 아니었다. 현행을 기준선으로
    #    놓고 2차 씨드(75쌍, --baseline current)로 직접 맞대니 뒤집힌다:
    #      100이 80을 이긴 비율  전체 46.7%(35-0-40) · 구간1 60.0% · 구간2 49.3% ·
    #                            구간3 40.0%(30-0-45)
    #    구간1에서만 이기고 전체창·구간3에서 진다 — 2026-08-03 근거 ④가 적어 둔 '최근
    #    구간에서 크게 진다'와 같은 방향이다. **구간이 갈리므로 기각, SMA80 유지 확정.**
    #    (평균 수익·MDD는 100이 근소 우위지만 승-무-패가 채택 규칙이다.)
    #  ④ [밴드는 ±1% 유지] ±2%가 전체·구간1·구간2에서 가장 강하지만 구간3에서 16-20으로
    #    진다. ±0%는 반대로 구간3에서 15-21로 진다. 구간이 갈리므로 둘 다 채택하지 않는다.
    MARKET_FILTER_BAND: float = Field(default=1.0, ge=0.0, le=10.0)  # 시장 필터 이탈 확인 밴드 (%, 0이면 단순 이탈 판정)
    # [중복 감사] 시장 필터(SMA80±1%)와 국면(EMA9/41)은 같은 지수 종가에서 나오는데도
    #  각각 독립으로 작동한다(판정 일치율 KOSPI 76.1%/KOSDAQ 73.5%). 켜면 국면이
    #  '확정 하락(Bear)'인 동안에는 밴드 이탈에 따른 신규 매수 차단을 해제한다.
    #
    # ┌─ [확정 기각 2026-08-04 / 재제안 불필요] ────────────────────────────────────
    # │ 아래 지수 기준 근거는 종목 단위에서 **재현되지 않는다**. tools/audit_market_bear_release.py
    # │ 로 실거래와 같은 41종목 전체를 슬롯 4개로 굴리며 250거래일 창을 25일씩 밀어
    # │ 39창(2021-08~2026-08)을 짝비교한 결과, 게이트가 일해야 하는 창에서 정확히 무너졌다.
    # │
    # │                    Δ수익      ΔMDD     수익승      최악MDD
    # │   하락 창(10창)    -9.8%p   -16.2%p    1/10    -22.6 → -30.8%   ← 게이트의 존재 이유
    # │   상승 창(23창)   +22.4%p    +0.0%p   17/23    -38.5 → -38.0%
    # │
    # │ 전체 중앙값만 보면 MAR +0.37(22/33승)로 좋아 보이지만, 그 이득은 전부 상승 창에서
    # │ 나온다. 상승 창의 'Bear'는 상승 추세 안의 짧은 눌림이라 되사면 이기는 게 당연하고,
    # │ 시장 필터는 애초에 그 구간을 위해 있는 장치가 아니다. 정작 2021~2022 하락장에서는
    # │ 낙폭이 -9%→-29% 로 세 배 깊어졌다. 상위10% 청산수익(fat-tail) 개선도 0.00 으로,
    # │ 추세추종 관점의 채택 근거인 '큰 추세를 더 잡는다'가 성립하지 않는다.
    # │
    # │ [왜 지수 근거가 틀렸나] 지수의 향후 20일 수익률은 평균회귀로 양수가 되지만, 개별
    # │  모멘텀 종목을 ATR 손절과 함께 사면 반등 전에 손절이 먼저 나간다. 게다가 그 포지션이
    # │  슬롯을 점유해 회복 국면의 진짜 진입까지 막는다. '지수를 산다'는 가정이 만든 착시다.
    # │  → 지수 프록시로 진입 게이트를 판단하지 말 것. 슬롯·손절이 있는 경로로 재야 한다.
    # │
    # │ [표본 설계 주의] 종목을 무작위 표본으로 뽑아 비교하면 결론이 표본 크기에 따라 흔들린다
    # │  (MAR 해제승: 12종목 55% → 20종목 78% → 30종목 90%). 유니버스가 41개뿐이라 표본을
    # │  키우면 시행끼리 겹쳐 승수가 부풀고, 줄이면 실거래와 다른 좁은 후보 풀을 재게 된다.
    # │  이 축은 반드시 --walk(전 종목 고정 · 시간축)로 판정할 것.
    # └───────────────────────────────────────────────────────────────────────────
    #
    # [기각된 근거 — 기록 보존] tools/audit_market_axes.py, KOSPI·KOSDAQ 2010~2026(각 4082거래일).
    #  게이트 차단일을 국면별로 쪼개면 '차단이 옳은 날'과 '차단이 손해인 날'이 정반대로 갈린다.
    #  (향후 20거래일 지수 수익률)
    #    게이트 ∧ 국면    KOSPI                        KOSDAQ
    #    PendDown        -0.30% 승률51.0% (n=865)      -0.32% 승률51.8% (n=962)   ← 차단이 옳다
    #    PendUp          +0.14% 승률53.3% (n=195)      -1.03% 승률41.1% (n=258)   ← 차단이 옳다
    #    Bear            +2.48% 승률69.8% (n=543)      +2.33% 승률67.0% (n=619)   ← 차단이 손해
    #    (전체 평균)      +0.86%                       +0.39%
    #  Bear 구간은 평균·승률뿐 아니라 하방 꼬리(하위10%)도 KOSPI -2.78%/KOSDAQ -6.23%로
    #  전체 평균(-4.92%/-7.07%)보다 안전했고, 3개 하위기간 × 2개 시장 = 6셀 전부 양수였다
    #  (KOSPI +2.67/+3.82/+1.62, KOSDAQ +3.59/+3.10/+1.12).
    #  이는 RISK_SCALING_PARAMS가 이미 채택한 결론과 같다 — 확정 Bear는 이미 -5% 하락한
    #  뒤라 반등 구간이고, 진짜 위험 구간은 PendDown이다(BEAR_RISK_SCALE=1.0 주석 참조).
    #  리스크 배수는 그 원칙을 따르는데 시장 필터만 따르지 않아, Bear 내내(전체 거래일의
    #  13~15%) 가장 좋은 진입 구간의 매수를 막고 있었다.
    #  ※ Bull/Sideways(판정 불가)에서는 해제하지 않는다 — fail-closed.
    #
    # [단서 — 자산곡선 기준으로는 시장별로 갈린다] tools/audit_axis_combination.py 로
    #  '지수에 배수만큼 노출한 자산곡선'을 만들어 재보면 위 향후수익률만큼 일방적이지 않다.
    #  현행(게이트+곱) 대비 Bear 해제를 추가했을 때, 3개 하위기간에서:
    #    KOSPI  CAGR 3/3 개선, Sharpe 3/3 개선(-0.30→-0.02, 0.56→0.62, 0.80→0.87), MDD 1/3 개선
    #    KOSDAQ CAGR 2/3, Sharpe 1/3 (2021~2026은 CAGR·MDD·Sharpe 모두 악화)
    #  즉 KOSPI에서는 견고하고, KOSDAQ에서는 견고하지 않으며 MDD는 대체로 나빠진다
    #  (Bear 구간에 노출하면 반등 전에 더 깊이 빠지는 경로를 겪기 때문).
    #  시장별로 따로 켜는 안은 표본이 2개뿐이라 과최적화 위험이 커 두지 않았다.
    #  ※ 이 단서(MDD는 대체로 나빠진다)가 종목 단위에서 결정적으로 드러난 것이 위 기각 사유다.
    #  구현은 남겨 둔다 — 되살리려는 시도가 나올 때 위 도구로 즉시 재현·기각하기 위해서다.
    MARKET_FILTER_RELEASE_ON_BEAR: bool = False
                                            #   종가 < SMA×(1-밴드)에서 차단, > SMA×(1+밴드)에서 해제, 사이는 직전 상태 유지.
                                            #   [검증 2026-08-03] 기간 조정보다 효과가 큰 레버다. SMA60에 1% 밴드만 얹어도
                                            #   경로 승률 76.9%·ΔCAGR +2.78%p·ΔMDD +3.45%p로 개선됐고, 격자 전반에서
                                            #   80~160일 × 밴드 1~2% 구간이 MAR 0.26~0.34의 고원을 이룬다.
                                            #   단 짧은 기간에 확인을 과하게 얹으면 역효과다(SMA60±2%는 ΔCAGR +0.06%p로 무개선,
                                            #   SMA60±1%+2일확인은 오히려 악화). 80일 × 1%가 검증된 조합이다.
    # [관찰 모드] 페이퍼 트레이딩 가상 시드(원). 실계좌 전환 예정 금액과 같게 두어야
    #  드로다운 금액·1주 미달로 버려지는 진입 기회까지 실제와 같은 조건에서 관찰된다.
    PAPER_SEED_CAPITAL: int = Field(default=10_000_000, gt=0)

    SYSTEM_MAX_CONSECUTIVE_ERRORS: int = Field(default=5, ge=1)  # [안전장치] 연속 에러 5회 발생 시 자동 중단
