    #    값을 흔들 이유도 없다. (일봉 재현이라 장중 발동은 과소평가된다 — 실제 발동은 더 잦다)
    SYSTEM_DAILY_LOSS_LIMIT: float = Field(default=10.0, ge=0.0)   # [안전장치] 일일 손실률 도달 시 자동 중단(비상 정지). 0.0%면 비상 정지 OFF(미사용)
    # [2026-08-18 · tools/audit_dials_intraday.py --only H] 2%/3%/5% 어느 값이든 장중 세계
    #  10년 45쌍에서 **0-45-0 · 소수점까지 동일**하다. 도구 함정이 아니라 구조다 —
    #  사이징 3층 min 결합에서 4슬롯이면 기초비중 25%가 항상 더 빡빡하다(리스크층은
