        #    +7%     341.3   24/60             2차    286.6   2-0-13
        #    +10%    402.0     —               3차    402.0     —
        #    +15%    321.1   20/60             5차    437.0   10-0-5 (4구간 29/60)
        #  5차는 전체 창에서 이기지만 4구간 29/60·구간1·3 열위·MDD -32.4·최대수익 144.6으로
        #  근거가 부족하다. 시드가 커져 현금 제약이 풀리면 다시 볼 축이다.
        #  [2026-08-18 계측기 수정 후 재실행 · 정정] 위 문장의 **'구간1 열위'는 재현되지 않는다.**
        #   5씨드(각 15회×25종목)로 다시 재니 전체창 11-0-4가 **다섯 씨드 전부** 나오고
        #   구간1·2·4도 5/5 승, 4구간 합은 36~44/60(평균 39)으로 채택선을 넘는다.
        #   갈리는 곳은 **구간3 하나**뿐이고 그마저 2승 3패다. 그런데도 미채택인 이유는
        #   ① 구간이 갈리고 ② **다섯 씨드 전부에서 MDD가 2.1~3.4%p 악화**하며
        #   ③ 꼬리(상위10%)가 3.0~4.7%p 얇아지기 때문이다(수익은 +80~99%p).
        #   즉 기각은 유지하되 **근거는 '구간1·3 열위'가 아니라 'MDD·꼬리와의 교환'이다.**
        #   장중 세계에서는 씨드2가 구간1 15-6-24·구간3 18-0-27로 무너지고 MAR승이
        #   세 씨드 전부 열위(12·14·17/45)라, 두 세계가 갈리는 것까지 확인됐다.
        #  ※ [오독 주의] 피라미딩 OFF의 fat-tail '지표'(상위10% 53.7·>30% 16건)가 더 좋아 보이지만
        #    이는 평단 상승에 따른 %수익률 희석이며, 절대 금액은 증액 쪽이 압도한다(113.8 vs 402.0).
        # [2026-08-16 · 장중 세계 재보정 · tools/audit_dials_intraday.py · 37종목·702일·15회×20종목·씨드3] **현행 유지.**
