        #  데이터가 시킨 변경이 아니라 **비용을 알고 한 운용자 선택**이다(2026-08-11).
        #  되돌리려면 이 값을 0으로 두면 종전 동작(발동·콜백 모두 3.5)으로 돌아간다.
        # [2026-08-16 · 장중 세계 재보정 · tools/audit_dials_intraday.py · 37종목·702일·15회×20종목·씨드3]
        #  **현행 유지 — 다만 양방향 후보가 하나씩 나왔고 둘 다 국면 의존이다.**
        #    배수   수익%   MDD%   무장%   전체창     구간1      구간2      구간3      대조
        #    3.0*   116.5  -16.6   31.0      —        —         —         —         —
        #    2.0    115.3  -16.8   48.1   19-0-26  27-4-14   31-1-13  21-10-14   29-8-8
        #    2.5    116.0  -16.5   40.8   26-0-19  24-18-3    29-8-8  20-12-13  15-18-12
        #    3.5    132.6  -16.7   26.4   32-0-13   21-3-21  10-11-24  22-11-12   31-0-14
        #  3.5(늦게 무장)는 전체창 32-0-13·MAR 31/45로 가장 강하고 MDD도 나빠지지 않는다.
        #  2.0(일찍 무장)은 정반대로 **구간에서는 이기는데 전체창은 진다**(19-0-26).
        #  즉 두 방향이 서로 다른 국면에서 이기고 3.0이 그 사이에 있다. 3.5는 구간2에서
        #  10-11-24로 지므로 기존 잣대(구간이 갈리면 채택하지 않는다)상 보류한다.
        #  ※ 재검토하려면 [[콜백 배수 4.5]]와 함께 볼 것 — 둘 다 '늦게 자른다'는 같은 방향이라
        #    동시에 넓히면 청산이 이중으로 늦어진다. 한 축씩 따로 재면 상호작용을 놓친다.
        #
        # [2026-08-17 합동 측정 · tools/audit_late_exit_joint.py] 위 '함께 볼 것'을 실행했다.
        #  같은 장중 세계·같은 프로토콜(45쌍)로 발동 3.5 · 콜백 4.5 · 트리거 +7%를 단독과
        #  조합으로 함께 걸었다. **답은 '이중 지연'이 아니라 '흡수'였다.**
        #   발동3.5 단독 132.6% (32-0-13) · 콜백4.5 단독 218.9% (41-0-4) ·
        #   **발동3.5+콜백4.5 218.9% — 콜백 단독과 다섯 창 전부 소수점까지 같다.**
        #   ※ [2026-08-19 재실행 정정] 계측기 수정 후 다시 재니 **네 창(전체·구간1·2·3)은
        #     여전히 소수점까지 같지만 대조구간(최근 고변동)에서는 갈린다**(32.0 vs 34.9,
        #     무장률 12.5 vs 21.4%). 흡수는 5/5가 아니라 4/5다 — 방향(발동 배수가 콜백에
        #     종속)은 그대로이나 '완전 흡수'라는 표현은 과했다.
        #   다른 것은 무장률뿐(31.3% → 26.2%). 콜백이 넓어지면 TS가 애초에 잘 안 걸려
        #   '언제 무장했는가'가 결과를 못 바꾼다. 상호작용 = 정확히 -(발동 단독 효과).
        #  [그래서 이 미결의 지위가 바뀐다] 발동 3.5는 **콜백을 3.5로 두는 한에서만** 독립
        #   후보다. 콜백을 넓히는 결정이 내려지면 이 축은 자동으로 무의미해진다 — 둘을
        #   따로 채택 심사할 이유가 없다. (반대로 콜백을 좁히는 쪽은 이미 확정 기각.)
        #  [트리거 +7%만 진짜 상호작용] 콜백4.5와 함께 걸면 218.9 → 257.2%, MAR 11.73 →
        #   13.24, 구간2를 -7.2 → +5.0%로 뒤집는다(35-0-10). 그러나 대조 구간(최근 고변동
        #   111일)에서는 30.6 → 28.6%, MDD -21.9 → -22.5로 **가장 나쁜 팔**이 된다.
        #  [결론] 세 미결 전부 보류 유지. 콜백 4.5의 기각 사유(최근 고변동 MDD 악화)는
        #   합동에서도 그대로다 — 콜백4.5 11-0-34 · 합동 12-0-33 · 셋 다 8-0-37.
