        #   창 경계의 **미실현 평가익**을 포함한다. 늦게 자르는 팔일수록 경계에서 포지션을
        #   더 많이 안고 끝나므로 짧은 구간에서 유리하게 나온다. 실측(구간1 197일):
        #     현행   총 1.9% = 실현 -0.7% + 미실현 2.9%
