        #   즉 구간1에서 콜백4.5가 '이긴' 54%p는 전부 아직 안 판 이익이고, 실현 손익만 보면
        #   오히려 더 나쁘다. 구간 단위 승패는 경계 위치에 민감하니 전체창·대조구간과 함께
        #   읽을 것. (평가액 기준 자체는 틀리지 않다 — 항상 4슬롯 만기 투자라 전체창에서도
        #   미실현 비중이 56~63%다. 문제는 짧은 창의 경계 효과다.)
        #   → **크기를 쟀다: 실재하나 판정을 뒤집지는 않는다** (tools/audit_subwindow_method.py,
