        #     경계 반납이 다음 구간에 정확히 청구된다. 두 세계·네 팔·구간 셋 = **판정 24개
        #     전부 동일**. 방향은 예상대로 — 늦게 자르는 팔이 독립 실행에서 부풀려진다
        #     (장중 구간3: 콜백4.5 172.6 → 147.4% · 셋 다 171.6 → 139.8%, 승수 최대 8 감소).
        #     기존 구간 판정을 다시 볼 필요는 없다.
