        #   저변동 창(2,338일): 수익 402.0(없음) vs 401.8(20%) · MDD -31.3 동일 · 상위10%·최대·
        #    >30% 동일 · 15회 중 7회는 소수점까지 동일 = 평시엔 사실상 없는 셈이다.
        #   고변동 창(111일): 무장률 20.7 → 30.8% · 미무장15+ 3건 → 1건 · 그 반납 32.6 → 19.3%p
        #    (수익 32.3 → 30.4로 소폭 낮으나 MAR은 1.53 → 1.58).
        #   캡 30%는 기각 — 배수 3.0에서는 거의 닿지 않아 목적 지표가 전혀 개선되지 않는데
        #    (미무장 3건·반납 32.6 그대로) 고변동 창에서만 크게 진다(수익 16.4 · MAR 0.89).
        #   캡 25%는 20%와 같은 방향의 절반 효과라 중간값으로 남길 이유가 없다.
