        # [부작용 · 감수하기로 한 것] 캡을 씌우면 무장이 '본전 도달선'보다 앞서 일어나므로
        #  무장 시 TS 청산선이 매수가 아래에 놓인다(예: ATR 9.5% 종목이 +20%에서 무장 →
        #  청산선 -13.3%). breakeven 모드가 원래 보장하던 '되돌림 한 번 맞아도 본전' 성질이
        #  캡 구간에서는 깨진다. 두 가지 복구안을 쟀고 **둘 다 기각**이다(2026-08-11):
