        #  캡 없는 배수 3.0에서도 '무장했는데 본전 아래 청산'은 무장 거래의 38.8%(435/1,120)이고
        #  TS 자체 청산 중에도 12.9%다 — 캡은 이 성질을 **악화**시킬 뿐 없던 문제를 만들지 않는다.
