        #  '무장 순간의 청산선이 매수가 위'(ATR/가격 ≥ 4.76%인 종목)라는 성질을 남기는 쪽을 택했다.
        #  ※ 캡을 다시 켜려면 20.0이 측정된 최적값이다(30%는 효과 0, 25%는 20%의 절반 효과).
