        #  대비 수익률(max_profit_rate × R)로 계산해, 수익이 클수록 캡이 과대평가되어 무력화됐다
        #  (MFE +108%, R=0.30이면 상한 32.5% → 실제 60%p 이상 반납 허용). 즉 위 실측의 '0.5'는
        #  의도한 반납 한도가 아니었으므로 그 결론을 그대로 재사용할 수 없다.
        #
        # [2026-07-29] engine.giveback_callback_cap()으로 MFE·R/(100+MFE) 환산하도록 수정하고
        #  재측정. 캐시 일봉 59종목 × 시작구간 6개(120~195):
        #             총손익      거래  평균보유  >30%거래  TS건당수익  조기청산
        #    R=0.00  1,193,405    583   15.0일     30건     20.82%       -
        #    R=0.25  6,279,697    802    9.4일     21건     12.04%     24건  ← 총손익 1위지만 기각
        #    R=0.35  5,050,953    775   10.0일     30건     12.13%     20건  ← 채택
        #    R=0.45  3,050,615    768   10.5일     26건     10.59%     19건
        #
        #  총손익만 보면 R=0.25가 최고지만, >30% 거래가 30→21건으로 깎여 fat-tail이 손상된다.
        #  캡은 MFE가 작을수록 강하게 조인다(MFE 20%면 상한 4.2% → 하한 5%로 바닥, ATR 동적
        #  콜백 10%대의 절반). 추세 초입의 정상 눌림에서 털리는 것이 조기청산의 실체다.
        #  실측 최악: 010120이 +43.6%(32일) 대신 +2.9%(1일)에 청산됐다.
        #  R=0.35는 >30% 거래 30건을 그대로 유지하면서(캡 해제와 동일) 총손익은 4.2배다.
        #  '주청산은 샹들리에 TS'라는 설계를 지키는 선에서의 최대치로 0.35를 택한다.
        #
        #  ※ 한계: 250봉 표본이라 >50% 대박 거래가 0건이고, 조기청산은 R과 무관하게 남는다
        #    (0.35에서도 20건). 다년 재검증은 메뉴 [4] 전략 백테스팅으로 수행할 것.
        #
