# ==========================================================
# [설정] 트랜잭션 속도 제한 (Rate Limiting)
# ==========================================================
REAL_TX_PER_SECOND = 20   # 실전투자 서버 최대 TPS: 20 (KIS 명목 한도)

# [최적화] 관심종목 멀티시세(FHKST11300006) 사용 여부.
# 메뉴2(종목 시세 분석) 국내 현재가를 30종목/1콜로 일괄 수집해 TPS 소모를 대폭 줄인다.
# (TR 미지원/오류 시 자동으로 종목별 조회 폴백)
USE_MULTI_PRICE = True

# [추가] 내부 TPS 안전계수 (Safety Margin)
# 위 *_TX_PER_SECOND는 운영자가 선언하는 '명목 한도'로 그대로 두고,
# 스로틀 로직 내부에서만 이 비율을 곱한 '실효 한도'로 운행한다.
# 이유: 명목 한도(예: 20)에 정확히 붙여 운행하면 클라이언트 1.1초 윈도우와
#       KIS 서버 1초 카운터의 경계가 충돌하여 EGW00201(초당 거래건수 초과)이
#       상시 발생한다. 약 10% 마진(실효 18 TPS)이면 20건이 ~1.06초에 분산되어
#       서버 1초 윈도우 기준 한도 미만으로 유지되며, 재시도 폭주가 사라져
#       오히려 실효 처리량이 안정된다. (1.0 = 마진 없음 / 값을 낮출수록 보수적)
# [#7] 적응형 동적 TPS (AIMD: 가산 증가·곱셈 감소)
#  명목 한도(20)에서 출발해, EGW00201이 나면 곱셈 감소로 물러나고 거부가 멎으면 다시
#  명목까지 완만히 되올린다. 즉 **실효 한도를 설정으로 못 박지 않고 서버가 알려주게 한다.**
#
# [실측 2026-08-09 · 고정 속도 스윕(tools/probe_kis_tps.py)]
#   앱키 2개(REAL·VIRT) × 기기 2대에서 동일한 무릎이 나왔다. 문서값 20 TPS는 성립하지 않는다.
#     · ~5 TPS : 거부 0%          · 6 TPS : 1.7%
#     · 7 TPS  : 12.9%            · 8 TPS : 14.4%
#   다만 단순 상한이 아니다 — 6을 넘겨도 성공 처리량은 계속 는다(10 TPS에서 8.9/s 성공).
#   초과분만 확률적으로 쳐내는 형태라 '낮출수록 좋다'가 성립하지 않는다. 그래서 값을 고정하지
#   않고 컨트롤러가 그날의 무릎을 찾게 둔다.
#
# [왜 종전 밴드가 잘못이었나] 종전은 [0.85, 0.98] = [17, 19.6]이었다. 실측 무릎(6)이 이 밴드
#  **전체보다 아래**라, 컨트롤러는 어떤 입력을 받아도 하한에 눌린 채 움직일 수 없었다.
#  실제로 운영 로그 495건(08-06~08-08)의 100%가 '하한 도달'이었다 — AIMD가 4일 내내 정지
#  상태였다는 뜻이다. 밴드가 실제 한도를 걸치지 못하면 적응 제어는 장식이 된다.
# [정책 2026-08-09] **속도 최우선.** 한도를 지키는 것보다 처리량이 중요하다는 운용 판단이다.
#  실측이 그 판단을 지지한다 — 성공 처리량은 목표 TPS에 단조 증가한다(고정 속도 스윕):
#      6 TPS → 5.92/s 통과(거부 0%)      10 TPS →  8.33/s (15.8%)
#      8 TPS → 6.83/s (14.6%)            20 TPS → 15.58/s (22.1%)
#  즉 거부는 초과분만 쳐낼 뿐 처벌이 아니고, 물러날수록 손해다. 명목 한도(20)에 붙여 운행하고
#  거부는 '싸게 재시도할 대상'으로 취급한다.
#  [남는 위험] 22% 거부를 상시 내는 것은 제공자 관점에서 곱게 보이지 않을 수 있다. 계정 제재
#  같은 조치가 관측되면 REAL_TPS_SAFETY_MIN 을 낮춰 컨트롤러에 권한을 돌려주는 것이 first aid다.
REAL_TPS_SAFETY = 1.0        # 시작값 = 명목 한도(20 TPS)
REAL_TPS_SAFETY_MAX = 1.0    # 상향 상한 = 명목 한도
REAL_TPS_SAFETY_MIN = 0.75   # 하한 15 TPS. 컨트롤러를 끄지는 않되, 물러날 수 있는 폭을 좁힌다
                             #  (속도 우선 정책이므로 최악에도 15 TPS 아래로는 안 내려간다)
TPS_ADAPT_STEP = 0.5         # 윈도우(1초)당 가산 증가폭. 15 → 20 회복에 10초
TPS_ADAPT_BACKOFF = 0.95     # 곱셈 감소율. 완만하게 — 거부는 비용이 아니라 신호일 뿐이다

# [Fix 2026-08-09] 곱셈 감소도 **윈도우당 한 번**이다(가산 증가와 같은 이유).
#  한 번의 초과에는 여러 스레드가 동시에 거부당한다. 그걸 건건이 곱하면 한 번의 혼잡에
#  배수가 수십 번 걸려 실효 한도가 바닥까지 무너진다 — 실제로 메뉴 2-5가 8배 느려졌다.
#  TCP의 곱셈 감소가 RTT당 1회인 것과 같다 — 같은 창의 추가 손실은 이미 반영된 것이다.
TPS_BACKOFF_WINDOW_SEC = 1.0

# [속도] 전송 간격을 균등하게 벌릴 것인가.
#  False면 1.1초 창 한도만 지키고 그 안에서는 몰아 보낸다(버스트 허용). 실측상 몰아 보내는
#  쪽이 처리량이 높다 — 30연결 폭주 측정에서 성공 처리량이 균등 전송보다 크게 나왔다.
#  균등 전송은 서버에 친절하지만 우리 목표가 아니다.
TPS_EVEN_PACING = False

# 매매용 예약분(TPS). 조회성 호출은 이만큼을 남겨 둔다.
#    조회 캡 = max(1, 실효 한도 - PRIORITY_RESERVE_TPS)
#  한도 20 기준 조회 18로, 속도 손실은 10%에 그치면서 매매 헤드룸은 절대량으로 지켜진다.
PRIORITY_RESERVE_TPS = 2.0

# 예약분을 실제로 떼어 둘지는 '매매가 지금 돌고 있는가'로 정한다. 이 시간 안에 우선순위
#  스레드의 전송이 없었으면 예약을 풀어 조회가 한도를 다 쓴다(자동매매 미가동 시 손실 0).
PRIORITY_RESERVE_IDLE_SEC = 10.0

# [TPS 우선순위] 조회성(메뉴) 호출에 남겨 두지 않고 **매매용으로 떼어 두는 예약분**(TPS).
#  매매 판단·주문은 시각이 곧 가격이라 미룰 수 없지만 조회 메뉴는 몇 초 늦어도 무방하다.
#  종전에는 비율(LOW_PRIORITY_TPS_SHARE=0.5)로 쪼갰는데, 실효 한도가 동적으로 변하면 비율은
#  틀린 도구다 — 한도 20에서 조회 10은 넉넉하지만 한도 6에서 조회 3은 메뉴가 못 쓸 만큼
#  느리고, 그러면서도 매매에 남는 몫은 3뿐이라 어느 쪽도 만족시키지 못한다.
#  절대량 예약으로 바꾸면 한도가 어디로 움직이든 매매 헤드룸은 그대로다.
#    조회 캡 = max(1, 실효 한도 - PRIORITY_RESERVE_TPS)
#    (한도 20 → 조회 18 · 한도 6 → 조회 4 · 한도 3 → 조회 1)
#  0으로 두면 종전처럼 조회·매매가 동등 경쟁한다.
PRIORITY_RESERVE_TPS = 2.0

# 거부 로그 집계 주기(초). 거부는 초당 수 건까지 나므로 건건이 WARNING을 남기면 로그가
#  그것만으로 찬다. 이 주기마다 한 줄로 묶어 남기되(첫 거부는 즉시), 사후에 상황을 재구성할
#  수 있는 값은 그 한 줄에 모두 담는다 — 전송률·실효 한도 궤적·최다 TR·스레드·누출·중복.
TPS_LOG_INTERVAL_SEC = 60

# [폐지 2026-08-25] APPKEY_DUP_ABORT — 앱키 중복은 이제 기본으로 기동을 막는다.
#  같은 모드가 두 번 뜨는 것을 차단하는 결정(main._enforce_single_instance)에 모드 잠금과
#  함께 흡수됐고, 예외는 --allow-duplicate 하나로 통일했다. 끄고 켜는 손잡이를 남겨 두면
#  '차단이 꺼져 있어서 두 개가 떴다'는 경로가 그대로 남는다.

def analysis_max_workers():
    """[#9] 종목 단위 외부 병렬 분석(KIS 경로)의 워커 수를 TPS에 정합시킨다.

    게이트(실효 TPS)보다 훨씬 많은 워커는 게이트 앞에서 대기만 하며 라즈베리파이 메모리를
    낭비한다. 동시에 in-flight 시킬 종목 수를 TPS에 비례해 제한한다.
    (모의 2 TPS→2, 실전 20 TPS→약 5). 토스는 별도 한도라 보수적으로 4를 쓴다.
    """
    try:
        if session.is_toss:
            return 4
        return max(3, min(6, int(REAL_TX_PER_SECOND / 4)))
    except Exception:
        return 4

# [추가] 토스증권 Open API 기본 호출 한도 (그룹별 토큰버킷이나, 보수적 단일 간격으로 운영)
# 토스 한도는 10/s → 최대치(10)로 운영한다.
TOSS_TX_PER_SECOND = 10

# ==========================================================
# [설정] 시세 개요 백그라운드 예열 (Overview Warmer)
# ==========================================================
# 해외 종목 시세/시장 지수를 백그라운드에서 주기적으로 마이크로 캐시에 채워,
# '시장 지수 조회'/'종목 시세 분석'(해외) 진입 시 임계경로 조회 없이 즉시 표시되게 한다.
#  - 국내 종목 현재가/체결강도는 KRX/NXT 무관하게 매 실행마다 라이브로 조회하므로 예열하지 않는다.
OVERVIEW_WARM_ENABLED = True          # 백그라운드 예열 사용 여부 (실전 계좌에서만 자동 동작)
OVERVIEW_WARM_INTERVAL_SEC = 15       # 예열 주기(초). 해외 시세/지수 fast_info 예열에 사용
#  예열 결과를 화면이 마지막으로 쓴 뒤 이 시간이 지나면 워머는 조회를 멈춘다(화면을 열면 재개).
#  예열은 사람이 개요를 볼 때만 값이 있는데, 종전에는 프로세스가 사는 내내 15초마다 돌아
#  아무도 보지 않는 새벽에도 외부 조회를 냈다(하루 5,760 사이클).
OVERVIEW_WARM_IDLE_SEC = 600          # 유휴 판정(초). 이 시간 동안 개요를 보지 않으면 예열 중단

# ==========================================================
# [설정] 실시간 시세 WebSocket (KIS 실전/모의)
# ==========================================================
# KIS는 단일 WS 연결당 41건(종목×TR) 등록 제한 + approval_key당 동시 연결 1개 제한이 있다.
# 보유종목 우선 구독 + 관심종목 로테이션으로 운용하고, 미구독/끊김 시 기존 REST로 자동 폴백한다.
# 토스(mode 3)는 공식 WS 미지원이라 REST 폴링을 유지한다(추후 WS 공개 시 어댑터 교체).
# (USE_WEBSOCKET 사용 여부 토글은 메뉴 0에서 변경 가능하도록 GlobalSettings(Pydantic) 필드로 둔다)
WS_MAX_REGISTRATIONS = 41         # KIS 단일 연결 등록 한도(종목×TR)
# 호가(H0STASP0) 구독 여부. SubscriptionManager.plan()이 현재가(H0STCNT0)를 먼저 등록해 종목
# 커버리지를 최대(=한도)로 확보한 뒤, 남는 등록 슬롯에만 호가를 best-effort로 얹으므로 현재가
# 커버리지는 절반으로 줄지 않는다. WS 호가 캐시는 api.get_ask_bid_ratio()의 수급 게이트가 소비하며,
# 이를 켜면 매수후보/매도조건 분석에서 종목당 호가 REST 1콜을 절감한다.
WS_SUBSCRIBE_ORDERBOOK = True
WS_DATA_TTL_SEC = 3.0             # WS 캐시 신선도(초): 이 시간 이내면 REST 대신 WS 값을 사용
WS_ROTATE_INTERVAL_SEC = 30       # 41건 초과분(관심종목) 구독 로테이션 주기(초)
WS_RECONNECT_BACKOFF_SEC = 5      # 연결 실패/끊김 시 재연결 대기(초)

# ==========================================================
# [설정] 파일 경로 관리
# ==========================================================
# 프로젝트 루트 디렉토리 및 서브 디렉토리 정의
BASE_DIR = os.path.dirname(os.path.abspath(__file__))

DB_DIR = os.path.join(BASE_DIR, "db")
CHART_DIR = os.path.join(BASE_DIR, "chart")
DATA_DIR = os.path.join(BASE_DIR, "data")
JSON_DIR = os.path.join(BASE_DIR, "json")
LOG_DIR = os.path.join(BASE_DIR, "logs")

# 디렉토리 자동 생성
for d in [DB_DIR, CHART_DIR, DATA_DIR, JSON_DIR, LOG_DIR]:
    if not os.path.exists(d):
        try: os.makedirs(d)
        except Exception: pass

# ==========================================================
# [차트 웹 대시보드] --webchart 로 켜는 갤러리 서버
# ==========================================================
# 실행 중 켜졌는지 여부. main.py 가 --webchart 를 받으면 True 로 올린다.
#  (차트 모듈이 '뷰어를 못 띄웠을 때 웹으로 안내할지'와 인덱스 갱신 여부를 이 값으로 가른다)
WEBCHART_ACTIVE = False

# [포트] 6000 을 쓰면 안 된다 — X11 포트라 Chromium·Firefox 의 restricted ports 목록에 있어
#  브라우저가 ERR_UNSAFE_PORT 로 막는다(curl·Safari 만 열린다). 헤드리스 파이의 차트를
#  브라우저로 보자는 기능이므로 차단 포트를 기본값으로 둘 수 없다.
#  같은 이유로 6566·6665~6669·6697·10080 등도 피한다. 9095 는 차단 목록에 없다.
WEBCHART_PORT = int(os.getenv("WEBCHART_PORT", "9095"))

# [바인딩] 기본은 전체 인터페이스 — 헤드리스 파이에 다른 기기에서 붙는 것이 이 기능의 목적이다.
#  인증이 없으므로 신뢰할 수 없는 망에 물린 서버라면 "127.0.0.1" 로 좁히고 SSH 터널을 쓴다.
WEBCHART_HOST = os.getenv("WEBCHART_HOST", "0.0.0.0")

# [차트 해상도] 메뉴에서 그리는 분석 차트의 DPI.
#  [왜 손잡이가 필요한가 · 2026-08-29] 렌더링 순간의 메모리 봉우리가 DPI 의 제곱으로 큰다.
#   실측(16x9 인치 기준, RSS 증가분):
#     dpi=100 → 1600x900,  +9MB   | dpi=150 → 2400x1350, +13MB
#     dpi=200 → 3200x1800, +22MB  | dpi=300 → 4800x2700, +53MB
#   matplotlib 자체가 이미 ~145MB 를 쓰므로, 1GB 라즈베리파이에서 300 DPI 봉우리는
#   리눅스 OOM Killer 를 부른다 — 실제로 2026-08-26 에 웹서버 프로세스가 이 이유로
#   죽었다(당시엔 별도 프로세스라 그것만 죽었고, 지금은 스레드라 앱 전체가 위험하다).
#   파이에서는 CHART_DPI=150 을 권한다(봉우리 1/4, 2400x1350 이면 읽기 충분).
#   기본값은 종전과 같은 300 이다 — 조용히 화질을 낮추지 않는다.
CHART_DPI = int(os.getenv("CHART_DPI", "300"))

# ==========================================================
# [거래비용] 백테스트·관찰모드·실거래 손익 기록이 공유하는 단일 소스
# ==========================================================
#  세 환경이 서로 다른 비용을 쓰면 성과를 비교할 수 없다. 백테스트가 좋아 보이는 것이
#  전략 때문인지 비용을 덜 뺐기 때문인지 분리되지 않기 때문이다. 실제로 2026-08-10
#  이전에는 백테스트에 매도 수수료만 있고(무명 리터럴 0.0023) 매수 수수료가 없었으며,
#  관찰모드는 반대로 수수료만 있고 슬리피지가 없었다.
#
#  이 값은 전략 다이얼이 아니라 증권사·세법이 정하는 사실이므로 설정 메뉴에 넣지 않는다.
#  증권사나 세율이 바뀌면 여기만 고친다. 산출 근거를 남겨 나중에 검산할 수 있게 한다.
#
#  [국내] 2026-08-10 실측 확인. 종전 값(매수 0.015% / 매도 0.23%)은 출처 없이 승계된
#   어림값이었다. 아래는 한국투자증권 공시 요율과 2026년 개정 세율로 다시 쌓은 것이다.
#
#   위탁수수료(뱅키스 온라인 HTS/MTS/API)  0.0140527%
#   유관기관 제비용(KRX)                   0.0036396%
#                                        ─────────────
#   편도 수수료 합                         0.0176923%
#
#   증권거래세(매도만, 2026-01-01 시행)     0.20%
#     · 코스피  거래세 0.05% + 농특세 0.15% = 0.20%
#     · 코스닥  거래세 0.20% (농특세 없음)  = 0.20%
#     양 시장이 같은 값이라 시장 구분 없이 하나로 둔다. 2025년까지는 0.15%였고
#     금투세 폐지에 따라 2023년 수준으로 환원됐다 — '인하 추세'로 착각하지 말 것.
#
#   매수 = 0.0176923%            → 0.000177
#   매도 = 0.0176923% + 0.20%    → 0.002177
#
#  [주의] 위 수수료는 **뱅키스(비대면) 계좌** 기준이다. 영업점 계좌는 같은 온라인
#   주문도 0.147%로 8배가 넘는다. 계좌 종류가 바뀌면 이 두 상수를 반드시 다시 잡을 것.
BUY_FEE_RATE = 0.000177
