# =========================================================================
# [추가] 토큰 발급 실패 원인 분류 + 공인 IP 화이트리스트 안내
# -------------------------------------------------------------------------
# 토스/한투 모두 '허용 IP(화이트리스트)'에 등록되지 않은 곳에서 접속하면 토큰
# 발급이 거부된다(토스: 403 access_denied "IP address not allowed", 한투:
# 연결 거부). 토큰 발급 함수가 실패 원인을 LAST_TOKEN_ERROR에 기록하면,
# preflight 등이 이를 참조해 "IP 미등록" 같은 구체적 안내를 노출한다.
#   값: 'IP_BLOCKED' | 'NETWORK' | 'AUTH' | None
# =========================================================================
LAST_TOKEN_ERROR = None

_PUBLIC_IP_CACHE = None
_PUBLIC_IP_CACHE_TS = 0.0


def set_last_token_error(kind):
    """토큰 발급 실패 원인을 전역에 기록한다(성공 시 None으로 초기화)."""
    global LAST_TOKEN_ERROR
    LAST_TOKEN_ERROR = kind


def get_public_ip(timeout=4, ttl=300):
    """현재 아웃바운드 공인 IP를 best-effort로 조회한다. 실패 시 None."""
    global _PUBLIC_IP_CACHE, _PUBLIC_IP_CACHE_TS
    import time
    import requests
    now = time.time()
    if _PUBLIC_IP_CACHE and now - _PUBLIC_IP_CACHE_TS < ttl:
        return _PUBLIC_IP_CACHE
    for url in ("https://api.ipify.org", "https://checkip.amazonaws.com"):
        try:
            r = requests.get(url, timeout=timeout)
            if r.status_code == 200 and r.text.strip():
                _PUBLIC_IP_CACHE = r.text.strip()
                _PUBLIC_IP_CACHE_TS = now
                return _PUBLIC_IP_CACHE
        except Exception:
            continue
    return None


def build_token_failure_help(is_toss=False):
    """토큰 발급 실패 시 사용자 안내 메시지(rich 마크업 문자열 리스트)를 만든다.

    LAST_TOKEN_ERROR 분류와 사업자(토스/한투)에 따라 안내를 다르게 구성한다.
      - IP_BLOCKED: 허용 IP(화이트리스트) 미등록. 토스 전용 분류다 — 토스는 허용 IP 등록이
                    필수지만, 한투(KIS Developers)는 개인 계정에 IP 등록 메뉴 자체가 없어
                    (실측 확인) IP 안내를 하지 않는다.
      - AUTH      : 앱키/시크릿 거부(한투 403 EGW00103 '유효하지 않은 AppKey' 포함).
                    한투는 키 불일치·만료 확인을 안내한다.
      - NETWORK   : 연결 거부/타임아웃. 서버 점검·네트워크 문제일 수 있으며,
                    토스는 화이트리스트 필수라 IP 미등록도 유력 원인으로 함께 안내한다.
    """
    kind = LAST_TOKEN_ERROR
    if kind not in ('IP_BLOCKED', 'NETWORK', 'AUTH'):
        return []

    lines = []

    if kind == 'AUTH':
        if is_toss:
            return []  # 토스 키 오류는 preflight 기본 문구로 충분
        # 한투: EGW00103 등 앱키 거부 — 키 자체 문제를 사실 기반으로 안내
        lines.append("  [bold yellow]→ 앱키/시크릿이 거부되었습니다 (예: EGW00103 '유효하지 않은 AppKey').[/bold yellow]")
        lines.append("     • KIS Developers → My App 에서 현재 발급된 AppKey/AppSecret과 ~/.htsrc 값이 일치하는지 확인하세요.")
        lines.append("       (키 재발급·유효기간(1년) 만료 시 기존 키는 무효화됩니다)")
        lines.append("     • 다른 기기에서 정상 동작 중이라면 그 기기의 ~/.htsrc 키와 값을 비교하세요.")
        return lines

    ip = get_public_ip()
    ip_str = f"[bold]{ip}[/bold]" if ip else "(확인 실패 — 네트워크 연결을 먼저 점검하세요)"

    if kind == 'IP_BLOCKED':
        # 허용 IP 미등록 — 토스 전용 안내 (한투 개인 계정에는 IP 등록 메뉴가 없음)
        if not is_toss:
            return []
        lines.append("  [bold yellow]→ 현재 공인 IP가 허용 IP(화이트리스트)에 등록되어 있지 않습니다.[/bold yellow]")
        lines.append(f"     • 현재 공인 IP: {ip_str}")
        lines.append("     • [토스] 토스증권 개발자센터 → 앱 설정 → 허용 IP 에 위 IP를 등록하세요.")
        lines.append("     • 또는 기존에 등록해 둔(고정 IP) 네트워크에서 실행하세요.")
        return lines

    # kind == 'NETWORK' : 연결 자체가 안 되는 상태
    if is_toss:
        # 토스는 화이트리스트가 필수 → IP 미등록을 유력 원인으로 함께 안내
        lines.append("  [yellow]→ 토스 API 서버에 연결하지 못했습니다. 서버 점검·네트워크 문제일 수 있으며,[/yellow]")
        lines.append("  [yellow]   토스는 허용 IP(화이트리스트) 등록이 필수이므로 현재 IP 미등록도 유력한 원인입니다.[/yellow]")
        lines.append(f"     • 현재 공인 IP: {ip_str}")
        lines.append("     • [토스] 토스증권 개발자센터 → 앱 설정 → 허용 IP 에 위 IP가 등록돼 있는지 확인하세요.")
    else:
        # 한투: 서버 상태·네트워크 확인 안내 (IP 화이트리스트 개념 없음)
        lines.append("  [yellow]→ 한투 API 서버에 연결하지 못했습니다(연결 거부/시간초과).[/yellow]")
        lines.append("  [yellow]   KIS 서버 점검·장애이거나 네트워크 문제일 가능성이 높습니다. 잠시 후 다시 시도하세요.[/yellow]")
        lines.append("     • KIS Developers 공지/서버 상태와 네트워크(방화벽·포트 9443/29443)를 확인하세요.")
    return lines

# [추가] 로그 파일명 변경을 위한 Namer 함수
def _log_namer(name):
    """
    로테이션된 로그 파일명을 '파일명_YYYYMMDD.log' 형태로 변경
    예: mystock.log.20260218 -> mystock_20260218.log
    """
    try:
        base, date_part = name.rsplit('.', 1) # logs/mystock.log, 20260218
        dir_name = os.path.dirname(base)
        file_name = os.path.basename(base) # mystock.log
        root, ext = os.path.splitext(file_name) # mystock, .log
        return os.path.join(dir_name, f"{root}_{date_part}{ext}")
    except Exception:
        return name

# [추가] 커스텀 로그 핸들러 클래스 (커스텀 Namer 사용 시 자동 삭제 버그 수정)
# ==========================================================
# [보안] 로그에 남는 민감정보 마스킹
# ==========================================================
#  [왜 필요한가] 예외 메시지는 URL·요청 본문을 통째로 물고 온다. requests 의
#   ConnectionError/Timeout 문자열이 대표적이다. 디버그 출력 쪽에는 이미 헤더 마스킹이
#   있었지만(call_api), 그 경로를 지나지 않는 예외 문자열은 그대로 파일에 남았다.
#
#  [실측 2026-08-10 / 30일치 로그] KIS 앱키·시크릿·토큰은 0건(마스킹이 동작 중).
#   반면 DART 인증키 4건, 계좌번호 11건이 평문이었다 — DART 는 인증키를 쿼리스트링에
#   싣고, KIS 조회 URL 은 CANO 를 쿼리로 보내기 때문이다.
#   로그를 다른 기계로 옮기거나 진단용으로 공유하면 그대로 따라 나간다.
#
#  [설계] 로깅 계층(Filter)에 둔다. 호출부마다 가리면 새 호출부가 생길 때마다 빠진다 —
#   실제로 마스킹이 있었는데도 예외 경로에서 새어나온 것이 그 증거다.
#   계좌번호는 뒤 4자리를 남긴다. 어느 계좌인지 구분하지 못하면 사후 추적이 안 된다.

_SENSITIVE_PATTERNS = [
    # 쿼리스트링 — 인증키·비밀키는 통째로 가린다
    (re.compile(r'((?:crtfc_key|appkey|appsecret|app_key|app_secret|secret|api_key|token)=)[^&\s"\')]+',
                re.IGNORECASE), r'\1***MASKED***'),
    # Authorization 헤더 값
    (re.compile(r'(Bearer\s+)[A-Za-z0-9._\-]+'), r'\1***MASKED***'),
    # 계좌번호 — 쿼리스트링 형태. 뒤 4자리만 남긴다
    (re.compile(r'(CANO=)\d+(\d{4})', re.IGNORECASE), r'\1****\2'),
    # 계좌번호 — JSON 본문 형태
    (re.compile(r'("CANO"\s*:\s*")\d+(\d{4})"'), r'\1****\2"'),
]

# 정규식을 돌리기 전 값싼 사전 검사. 라즈베리파이에서 DEBUG 로그를 켜면 이 필터가
#  모든 레코드를 지나므로, 대다수인 '민감정보 없는 줄'을 문자열 검색으로 먼저 걷어낸다.
_SENSITIVE_HINTS = ("crtfc_key", "CANO", "cano=", "Bearer ", "appkey", "appsecret",
                    "app_key", "app_secret", "api_key", "token=", "secret=")


def mask_sensitive(text):
    """로그 문자열에서 인증키·계좌번호를 가린다. 실패해도 원문을 돌려준다."""
    if not text:
        return text
    try:
        if not any(h in text for h in _SENSITIVE_HINTS):
            return text
        for pattern, repl in _SENSITIVE_PATTERNS:
            text = pattern.sub(repl, text)
    except Exception:
        pass
    return text


class SensitiveDataFilter(logging.Filter):
    """모든 로그 레코드에서 민감정보를 가린다(핸들러가 아니라 레코드를 고친다).

    포맷 이후가 아니라 레코드 단계에서 고쳐야 파일·콘솔 어느 핸들러로 가든 함께 가려진다.
    """

    def filter(self, record):
        try:
            msg = record.getMessage()
        except Exception:
            return True
        masked = mask_sensitive(msg)
        if masked != msg:
            record.msg = masked
            record.args = ()
        return True


class CustomTimedRotatingFileHandler(TimedRotatingFileHandler):
    """커스텀 namer(_log_namer)를 사용할 때 내장 getFilesToDelete가 파일을 인식하지 못해 삭제되지 않는 문제를 해결한 클래스"""
    def getFilesToDelete(self):
        dirName, baseName = os.path.split(self.baseFilename)
        fileNames = os.listdir(dirName)
        result = []
        
        root, ext = os.path.splitext(baseName)
        prefix = root + "_" # 예: mystock_
        date_pattern = re.compile(r'^\d{8}$') # %Y%m%d
        
        for fileName in fileNames:
            if fileName.startswith(prefix) and fileName.endswith(ext):
                date_part = fileName[len(prefix):-len(ext)]
                if date_pattern.match(date_part):
                    result.append(os.path.join(dirName, fileName))
        
        if len(result) < self.backupCount:
            result = []
        else:
            result.sort()
            # 지정된 보존 개수를 초과하는 가장 오래된 파일들을 반환
            result = result[:len(result) - self.backupCount]
        return result

# [추가] 시스템 시작 표시 전용 로거 이름.
#  FILE_DEBUG_LEVEL(기본 WARNING)과 무관하게 항상 INFO 로 기록되도록 setup_logging 에서
#  이 로거의 레벨만 따로 낮춰 준다.
STARTUP_LOGGER_NAME = "startup"

# [추가] 로깅 설정 초기화 함수
def setup_logging():
    # 기존 레벨 저장 (변경 감지용)
    root_logger = logging.getLogger()
    prev_level_no = root_logger.level
    prev_level_name = logging.getLevelName(prev_level_no) if prev_level_no != logging.NOTSET else "초기화 전"

    # 기존 핸들러 제거 로직은 logging.basicConfig(force=True)가
    # handler.close()를 포함해 안전하게 처리하므로 리스트 순회 삭제 버그를 발생시키는 수동 루프를 제거합니다.

    # 로깅 활성화
    logging.disable(logging.NOTSET)

    if not os.path.exists(LOG_DIR):
        try:
            os.makedirs(LOG_DIR)
        except Exception as e:
            print(f"[Config] LOG_DIR creation error: {e}")

    # [수정] 오래된 로그 파일 정리 (과거 패턴 및 핸들러 버그로 누적된 파일 강제 정리)
    try:
        if LOG_RETENTION_DAYS > 0 or AUTOTRADE_LOG_RETENTION_DAYS > 0:
            today = datetime.now().date()
            for filename in os.listdir(LOG_DIR):
                file_path = os.path.join(LOG_DIR, filename)
                
                try:
                    # 1. 기존 system_trade_YYYY-MM-DD.log 정리
                    if filename.startswith("system_trade_") and filename.endswith(".log"):
                        date_part = filename.replace("system_trade_", "").replace(".log", "")
                        file_date = datetime.strptime(date_part, "%Y-%m-%d").date()
                        if LOG_RETENTION_DAYS > 0 and file_date < today - timedelta(days=LOG_RETENTION_DAYS):
                            os.remove(file_path)
                    
                    # 2. 누적된 mystock_YYYYMMDD.log 및 autotrade_YYYYMMDD.log 강제 정리
                    #    자동매매 로그는 감사 증거이므로 별도(더 긴) 보존 기간을 쓴다.
                    elif (filename.startswith("mystock_") or filename.startswith("autotrade_")) and filename.endswith(".log"):
                        match = re.search(r'_(\d{8})\.log$', filename)
                        if match:
                            date_part = match.group(1)
                            file_date = datetime.strptime(date_part, "%Y%m%d").date()
                            limit = (AUTOTRADE_LOG_RETENTION_DAYS
                                     if filename.startswith("autotrade_") else LOG_RETENTION_DAYS)
                            if limit > 0 and file_date < (datetime.now().date() - timedelta(days=limit)):
                                os.remove(file_path)
                except Exception as e:
                    print(f"[Config] Old log file remove error ({filename}): {e}")
    except Exception as e:
        print(f"[Config] Old log cleanup process error: {e}")

    log_filename = "mystock.log" # [수정] 고정 파일명 사용
    log_filepath = os.path.join(LOG_DIR, log_filename)

    # [수정] CustomTimedRotatingFileHandler 적용 (백업 파일 삭제 버그 수정)
    file_handler = CustomTimedRotatingFileHandler(
        log_filepath, when='midnight', interval=1, backupCount=LOG_RETENTION_DAYS, encoding='utf-8'
    )
    file_handler.suffix = "%Y%m%d"
    file_handler.namer = _log_namer

    # [수정] 로그 포맷에 파일명과 라인 번호 추가
    file_handler.setFormatter(logging.Formatter('%(asctime)s.%(msecs)03d [%(levelname)s] [%(threadName)s] %(filename)s:%(lineno)d - %(message)s', datefmt='%H:%M:%S'))
    
    # 파일 로그 레벨 설정
    level_name = settings.FILE_DEBUG_LEVEL.upper()
    numeric_level = getattr(logging, level_name, logging.INFO)

    logging.basicConfig(level=numeric_level, handlers=[file_handler], force=True)
    
    # [추가] 외부 라이브러리 로그 레벨 조정 (노이즈 감소)
    for lib in ["httpcore", "httpx", "urllib3", "google", "google.genai", "mistune", "markdown_it", "yfinance", "peewee"]:
        logging.getLogger(lib).setLevel(logging.WARNING)

    # [추가] 매매일지 웹서버 연동 로그는 FILE_DEBUG_LEVEL 과 무관하게 항상 INFO 이상을 남긴다.
    #  기본 파일 로그 레벨이 WARNING 이라 연동 시작·전송 완료 같은 '정상 동작' 기록이 통째로
    #  사라지는데, 외부 서버로 나가는 전송은 무엇이 언제 나갔는지 사후 추적이 되어야 한다.
    #  (자식 로거의 레벨만 낮추면 되고, 루트 핸들러는 레벨 필터가 없어 그대로 파일에 기록된다.
    #   FILE_DEBUG_LEVEL=DEBUG 로 더 자세히 보려는 경우는 그 설정을 존중한다.)
    logging.getLogger("modules.journal_sync").setLevel(min(numeric_level, logging.INFO))

    # [추가] 시스템 시작 표시는 FILE_DEBUG_LEVEL 과 무관하게 항상 남긴다.
    #  로그 파일은 하루 단위로만 나뉘어 한 파일에 여러 번의 실행이 섞인다. 어디서부터가
    #  이번 실행인지 가르는 기준선이 없으면 사후 추적이 사실상 불가능하다.
    #  (기본값 WARNING 에서는 이 한 줄마저 통째로 사라진다)
    logging.getLogger(STARTUP_LOGGER_NAME).setLevel(min(numeric_level, logging.INFO))

    # [추가] urllib3 커넥션 재시도 WARNING 억제.
    #  KIS 서버가 idle keep-alive 연결을 먼저 끊어(RemoteDisconnected) 발생하는
    #  "Retrying (Retry(total=...)) after connection broken by ..." 경고는 어댑터가
    #  자동 재시도로 자가 치유하는 정상 동작이라 로그 노이즈일 뿐이다.
    #  (요청 간격이 길면 연결이 오래 idle 상태가 되어 더 빈번). ERROR로 올려 숨긴다.
    logging.getLogger("urllib3.connectionpool").setLevel(logging.ERROR)

    # [추가] 데이터 라이브러리의 '예상된 실패' ERROR를 DEBUG로 강등.
    #  야후 미제공 심볼(^K200FUT/^VKOSPI/^KQ150/^US02Y 등)의 404/"possibly delisted"와
    #  tvDatafeed 익명 웹소켓의 일시 끊김("Connection ... lost", "no data")은 자체 폴백·재시도로
    #  처리되는 설계상 정상 경로라 ERROR가 아니다. 핸들러 필터로 레벨을 낮춰(자식 로거 전파 포함)
    #  FILE_DEBUG_LEVEL=DEBUG일 때만 [DEBUG]로 기록한다. 우리 코드의 ERROR는 영향 없음.
    # [추가] 라이브러리의 '설계상 정상' WARNING도 강등 대상. (name, 메시지 조각) → 강등 레벨
    #  tvDatafeed 익명(nologin) 사용 경고는 우리가 의도적으로 선택한 접속 방식이라
    #  매 초기화마다 반복될 뿐 조치할 것이 없다 → INFO로 낮춘다.
    _DEMOTE_WARNINGS = (
        ("tvDatafeed", "you are using nologin method", logging.INFO),
    )

    class _DemoteExpectedLibErrors(logging.Filter):
        _NOISY = ("yfinance", "tvDatafeed", "websocket")

        @staticmethod
        def _is_lib(record, name):
            return record.name == name or record.name.startswith(name + ".")

        def filter(self, record):
            if record.levelno >= logging.ERROR and any(
                    self._is_lib(record, n) for n in self._NOISY):
                record.levelno = logging.DEBUG
                record.levelname = "DEBUG"
                return numeric_level <= logging.DEBUG

            if record.levelno == logging.WARNING:
                for lib_name, needle, target_level in _DEMOTE_WARNINGS:
                    if self._is_lib(record, lib_name) and needle in str(record.msg):
                        record.levelno = target_level
                        record.levelname = logging.getLevelName(target_level)
                        return numeric_level <= target_level
            return True

    file_handler.addFilter(_DemoteExpectedLibErrors())
    # [보안] 인증키·계좌번호 마스킹. 예외 메시지가 URL·본문을 통째로 물고 오므로
    #  호출부가 아니라 로깅 계층에서 가린다.
    file_handler.addFilter(SensitiveDataFilter())
        
    msg_level = max(numeric_level, logging.INFO)
    
    if prev_level_name not in ("초기화 전", level_name):
        logging.log(msg_level, f"=== 로깅 시스템 설정 변경 (파일 로그 레벨: {prev_level_name} -> {level_name}) ===")
    else:
        logging.log(msg_level, f"=== 로깅 시스템 설정 갱신 (현재 파일 로그 레벨: {level_name}) ===")


def log_system_start():
    """프로그램 구동 시작을 파일 로그에 한 줄로 남긴다.

    setup_logging() 직후에 호출한다. 전용 로거를 쓰는 이유는 FILE_DEBUG_LEVEL 이
    기본값(WARNING)이면 루트 로거의 INFO 가 막혀 이 한 줄까지 사라지기 때문이다.
    """
    level_name = settings.FILE_DEBUG_LEVEL.upper()
    logging.getLogger(STARTUP_LOGGER_NAME).info(
        f"=== MyStock HTS 시스템 시작 "
        f"(PID {os.getpid()}, 파일 로그 레벨: {level_name}) ===")

# [추가] 시스템 트레이딩 전용 로거 설정 함수
def get_autotrade_logger():
    """시스템 트레이딩 로그(autotrade.log)를 위한 로거 반환"""
    logger = logging.getLogger("autotrade")
    
    # [수정] 기존 핸들러가 있다면 모두 제거하고 새로 설정 (파일 생성 보장 및 중복 방지)
    # [수정] removeHandler만 하면 FileHandler가 파일을 연 채 분리되어 ResourceWarning
    #        (unclosed file)이 발생하므로, 제거 전에 close()로 파일 핸들을 확실히 닫는다.
    if logger.hasHandlers():
        for h in list(logger.handlers):
            try:
                h.close()
            except Exception:
                pass
            logger.removeHandler(h)
        
    logger.setLevel(logging.INFO)
    logger.propagate = False # 루트 로거로 전파 방지
    
    # [추가] 로그 디렉토리 확인 및 생성 (파일 생성 에러 방지)
    if not os.path.exists(LOG_DIR):
        try:
            os.makedirs(LOG_DIR)
        except Exception as e:
            print(f"[Config] Autotrade LOG_DIR creation error: {e}")

    log_filename = "autotrade.log"
    log_filepath = os.path.join(LOG_DIR, log_filename)
    
    # [수정] CustomTimedRotatingFileHandler 적용 (백업 파일 삭제 버그 수정)
    handler = CustomTimedRotatingFileHandler(
        log_filepath, when='midnight', interval=1,
        backupCount=AUTOTRADE_LOG_RETENTION_DAYS, encoding='utf-8', delay=False
    )
    handler.suffix = "%Y%m%d"
    handler.namer = _log_namer
    
    # 메시지만 출력 (타임스탬프는 AutoTrader가 메시지에 포함해서 보냄)
    handler.setFormatter(logging.Formatter('%(message)s'))
    handler.addFilter(SensitiveDataFilter())   # [보안] 인증키·계좌번호 마스킹

    logger.addHandler(handler)
    return logger

# ===========================================================================
# 모드별 설정 프로필
# ===========================================================================
# [문제] dynamic_config.json 은 한 벌뿐이라 모든 모드가 같은 파일을 읽고 썼다.
#  가상투자(mode 1)에서 검증하려고 시장 필터를 끄면 그 값이 그대로 남아, 다음에
#  실전(mode 2)으로 띄울 때도 필터가 꺼진 채로 돈다. 방어선은 기동 시 경고 하나뿐이었고
#  (main.py warn_if_safety_switches_off), 그건 '사람이 경고를 읽는가'에 기대는 장치다.
#
# [구조] 실전은 기준 파일(dynamic_config.json)만 읽고 쓴다. 실전이 아닌 모드는 자기
#  프로필 파일(dynamic_config.<프로필>.json)을 하나 더 얹는다.
#      실전(mode 2)   → dynamic_config.json
#      가상(mode 1)   → dynamic_config.json + dynamic_config.paper.json
#      토스(mode 3)   → dynamic_config.json + dynamic_config.toss.json
#  프로필 파일에는 **기준과 다른 값만** 적힌다. 그래서 (1) 실전 설정을 바꾸면 다른
#  모드도 따라오고(검증 조건이 운용 조건에서 멀어지지 않는다), (2) 다른 모드에서 바꾼
#  값은 그 파일에만 남아 실전으로 새지 않는다. 파일을 열어 보면 '이 모드가 실전과
#  무엇이 다른가'가 그대로 보인다.
#
# [승격은 수동] 관찰모드에서 좋았던 값을 실전에 쓰려면 실전으로 띄워 다시 바꿔야 한다.
#  자동으로 올려주지 않는 것이 요점이다 — 검증용으로 끈 안전장치가 조용히 따라 올라오는
#  경로를 없애는 것이 이 구조의 목적이기 때문이다.
_MODE_PROFILES = {
    '1': 'paper',   # 가상투자(관찰 모드)
    '2': None,      # 실전 = 기준 파일 그 자체
    '3': 'toss',
}
#  프로필 파일에서 '얹는' 대상이 되는 중첩 딕셔너리 그룹(스칼라 키는 그대로 덮어쓴다)
_CONFIG_GROUP_KEYS = ["ANALYSIS_THRESHOLDS", "SELL_STRATEGY", "INDICATOR_PARAMS",
                      "SCORING_WEIGHTS", "MARKET_REGIME_PARAMS", "RISK_SCALING_PARAMS"]

active_profile = None      # None = 실전(기준 파일). 모드 결정 시 set_config_profile()이 정한다.


def profile_for_mode(mode):
    """세션 모드 문자열('1'~'3') → 프로필 이름. 모르는 값은 실전 프로필(기준 파일)을 돌려준다.

    [주의] 여기서 None(=실전 설정)이 나와도 **거래 모드가 실전이 되지는 않는다** —
     모드 자체의 유효성은 core/session.SessionManager.initialize 가 화이트리스트로
     판정하고, 모르는 값이면 기동을 중단한다(fail-closed).
    """
    return _MODE_PROFILES.get(str(mode), None)


def base_config_path():
    return os.path.join(JSON_DIR, "dynamic_config.json")


def profile_config_path(profile=None):
    """현재(또는 지정) 프로필의 덮어쓰기 파일 경로. 실전이면 기준 파일 경로."""
    profile = active_profile if profile is None else profile
    if not profile:
        return base_config_path()
    return os.path.join(JSON_DIR, f"dynamic_config.{profile}.json")


def set_config_profile(profile):
    """모드가 정해진 직후 호출 — 프로필을 걸고 설정을 다시 읽는다.

    초기화와 재적용을 한 잠금 안에서 끝낸다(_settings_lock 은 RLock 이라 중첩 획득이
    가능하다). 나누면 그 사이에 다른 스레드가 '기본값만 적용된 중간 상태'를 읽는다.
    """
    global active_profile, settings
    with _settings_lock:
        active_profile = profile or None
        settings = GlobalSettings()      # 지난 프로필의 잔재를 남기지 않는다
        load_dynamic_config()


def _apply_config_data(data):
    """읽어 들인 설정 딕셔너리 한 벌을 현재 settings 위에 적용한다."""
    global settings
    with _settings_lock:
        current_dict = getattr(settings, 'model_dump', settings.dict)()

        for key in _CONFIG_GROUP_KEYS:
            if key in data:
                current_dict[key].update(data[key])
                del data[key]

        # [마이그레이션] 구버전 가격모멘텀(MOMENTUM_PRICE) 가중치는 제거하고 추세(TREND)로 흡수
        #   (총점 10점 유지: 추세4/모멘텀2.5/강도1.5/시너지2.0 체계로 복귀)
        sw = current_dict.get("SCORING_WEIGHTS", {})
        if "MOMENTUM_PRICE" in sw:
            sw["TREND"] = round(sw.get("TREND", 4.0) + sw.pop("MOMENTUM_PRICE", 0.0), 2)

        current_dict.update(data)
        settings = GlobalSettings(**current_dict)


def _read_config_file(path):
    """설정 파일 한 벌을 읽는다. 없으면 None(정상), 손상이면 격리 후 None.

    jsonio 를 쓴다 — 종전에는 여기서 직접 열어 읽고, 손상 시 한 줄 출력하고 None 을
    돌려줬다. 그러면 사용자가 조정한 리스크 파라미터 전부가 조용히 클래스 기본값으로
    되돌아간다(그 상태로 저장이 한 번 일어나면 원본도 사라진다). jsonio 는 깨진 파일을
    `.corrupt.<타임스탬프>` 로 치워 원본을 지키고 화면에도 알린다.
    """
    from core import jsonio
    return jsonio.load_json(path, default=None)


def diff_against_base(data, base=None):
    """현재 설정 한 벌에서 기준 파일과 다른 부분만 추린다(프로필 파일에 적을 내용).

    중첩 그룹은 키 단위로 비교한다 — 그룹 하나가 통째로 복사되면 그 뒤 실전 쪽 변경이
    프로필에 반영되지 않아, 프로필이 기준에서 조용히 굳어 버린다.
    """
    if base is None:
        base = _read_config_file(base_config_path()) or {}
    defaults = getattr(GlobalSettings(), 'model_dump', GlobalSettings().dict)()

    out = {}
    for key, value in data.items():
        if key in _CONFIG_GROUP_KEYS and isinstance(value, dict):
            base_group = dict(defaults.get(key) or {})
            base_group.update(base.get(key) or {})
            sub = {k: v for k, v in value.items() if base_group.get(k) != v}
            if sub:
                out[key] = sub
            continue
        base_value = base[key] if key in base else defaults.get(key)
        if base_value != value:
            out[key] = value
    return out


def save_dynamic_config(data):
    """설정 저장 — 실전이면 기준 파일에 전부, 그 외 모드면 프로필 파일에 차이만 쓴다.

    저장 경로를 이 한 곳으로 모은다. 메뉴(modules/settings.py)도 이 함수를 부른다 —
    '어느 파일에 무엇을 쓸지'가 두 곳에 있으면 한쪽만 고쳐져 모드 분리가 조용히 샌다.
    반환값은 실제로 쓴 경로이며, 실패하면 None 이다.
    """
    from core import jsonio
    path = profile_config_path()
    payload = data if not active_profile else diff_against_base(data)
    return path if jsonio.save_json(path, payload) else None


# [추가] 동적 설정 로드 함수 (사용자가 변경한 설정을 덮어씌움)
def load_dynamic_config():
    """기준 파일을 먼저 적용하고, 프로필이 걸려 있으면 그 위에 덮어쓴다."""
    base = _read_config_file(base_config_path())
    if base is not None:
        _apply_config_data(base)
    if active_profile:
        overlay = _read_config_file(profile_config_path())
        if overlay is not None:
            _apply_config_data(overlay)


# [추가] 커스텀 변경된 설정 내역 추출
def get_custom_settings():
    default_settings = getattr(GlobalSettings(), 'model_dump', GlobalSettings().dict)()
    current_settings = getattr(settings, 'model_dump', settings.dict)()
    
    changed_items = {}
    for k, v in current_settings.items():
        if k in ["ACTIVE_PRESET"]: continue
        default_v = default_settings.get(k)
        if isinstance(v, dict) and isinstance(default_v, dict):
            for sub_k, sub_v in v.items():
                sub_default = default_v.get(sub_k)
                if sub_v != sub_default:
                    changed_items[f"{k}.{sub_k}"] = {"parent": k, "key": sub_k, "default": sub_default, "current": sub_v}
        else:
            if v != default_v:
                changed_items[k] = {"parent": None, "key": k, "default": default_v, "current": v}
    return changed_items

# [추가] 지정된 커스텀 설정을 초기화하고 다시 로드
def reset_custom_settings(keys_to_reset):
    global settings
    import json
    #  지금 쓰고 있는 파일에서 지운다 — 관찰모드에서 되돌린 값이 실전 기준 파일을
    #  건드리면 안 되고, 그 반대도 마찬가지다.
    config_path = profile_config_path()
    
    if not os.path.exists(config_path):
        return

    with _settings_lock:
        try:
            from core import jsonio
            data = jsonio.load_json(config_path, default=None)
            if data is None:
                #  손상 파일은 jsonio 가 격리하고 알린다. 여기서 빈 딕셔너리로 이어가면
                #  '되돌리기'가 설정 전체를 날리는 동작이 되므로 그만둔다.
                return

            for key_path in keys_to_reset:
                if '.' in key_path:
                    parent, child = key_path.split('.', 1)
                    if parent in data and child in data[parent]:
                        del data[parent][child]
                        if not data[parent]:
                            del data[parent]
                else:
                    if key_path in data:
                        del data[key_path]

            from core import jsonio
            jsonio.save_json(config_path, data)
            
            # 초기 상태를 베이스로 새 설정 덮어씌우기
            #  (재적용까지 한 잠금 안에서 끝낸다 — 나누면 그 사이에 다른 스레드가
            #   '기본값만 적용된 중간 상태'를 읽는다. RLock 이라 중첩 획득은 안전하다.)
            settings = GlobalSettings()
            load_dynamic_config()
            setup_logging()  # 초기화된 파일 로그 레벨 즉시 적용
        except Exception as e:
            print(f"[Config] 설정 초기화 중 오류: {e}")

# [추가] 모든 커스텀 설정 삭제 및 시스템 기본값으로 완전 초기화
def reset_all_settings():
    """현재 프로필의 설정 파일을 지우고 클래스 기본값으로 되돌린다.

    [단일 소스] 종전에는 여기서 ANALYSIS_THRESHOLDS·SELL_STRATEGY·SCORING_WEIGHTS·
     MARKET_REGIME_PARAMS·RISK_SCALING_PARAMS·INDICATOR_PARAMS 여섯 딕셔너리를 통째로
     다시 타이핑했다. 그 결과 기본값이 (1) GlobalSettings 클래스 (2) 이 초기화 딕셔너리
     (3) json/dynamic_config.json 세 곳에 있었고, 실제로 한쪽만 고쳐지는 사고가 두 번
     났다 — 2026-08-05 RISK_SCALING 의 DD_SCALE 이 기각된 구 값(0.75/0.5)으로 되돌아갔고,
     2026-08-09 동적 ATR 캡 8키가 이 경로에서만 빠져 '전체 초기화'를 누르면 설정 파일이
     조용히 퇴화했다. 둘 다 '초기화를 눌렀더니 옛날 전략으로 돌아간다'는 형태의 사고다.
     지금은 클래스 기본값 한 곳만 진실이고, 초기화는 그것을 새로 읽어 온다.

    [왜 이제 안전한가] 하드코딩의 명목은 '클래스 딕셔너리 메모리 참조 오염 방지'였다.
     pydantic 은 v1·v2 모두 인스턴스마다 가변 기본값을 복사해 준다 — GlobalSettings()를
     새로 만들면 이전 인스턴스에서 제자리 수정(config.ANALYSIS_THRESHOLDS['X']=1)한
     내용이 따라오지 않는다. tests/test_config_defaults.py 가 이 성질을 고정한다.
    """
    global settings
    import os
    #  실전에서 누르면 기준 파일이, 관찰모드에서 누르면 관찰 프로필만 지워진다.
    config_path = profile_config_path()
    if os.path.exists(config_path):
        try: os.remove(config_path)
        except Exception: pass

    with _settings_lock:
        settings = GlobalSettings()

        import sys
        current_module = sys.modules[__name__]
        settings_keys = getattr(settings, 'model_dump', settings.dict)().keys()

        for key in settings_keys:
            if key in current_module.__dict__:
                del current_module.__dict__[key]

        #  프로필을 지운 경우 기준 파일은 그대로다 — 다시 읽어 기준 설정으로 복귀시킨다.
        if active_profile:
            load_dynamic_config()

