# 모듈 로드 시 자동 실행
load_dynamic_config()

# 기존 코드 호환용 PEP 562 모듈 레벨 __getattr__ 래퍼
def __getattr__(name):
    if hasattr(settings, name):
        with _settings_lock:
            return getattr(settings, name)
    raise AttributeError(f"module '{__name__}' has no attribute '{name}'")
